// ---- Affiliate program (commission payouts on referrals) ----
model AffiliatePayout {
  id          String    @id @default(cuid())
  userId      String
  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)
  amountCents Int
  status      String    @default("PENDING") // PENDING | APPROVED | PAID | DECLINED
  note        String?
  createdAt   DateTime  @default(now())
  paidAt      DateTime?
}

// ---- KOL / Agency partner program (lifetime per-customer attribution) ----
//
// DISTINCT from the peer-referral program above (User.referralCode/referredById +
// AffiliatePayout), which pays a ONE-TIME wallet bonus to a customer who refers a
// friend. This program is for agencies / content creators (KOLs) who bring on
// customers and then earn a LIFETIME percentage on EVERY qualifying charge that
// customer ever makes — initial orders AND renewals, across every product. The
// partner stays permanently attached to the customer.
//
// All three models are additive and never alter an existing table.

/// An agency or content creator (KOL) partner. `code` is the referral code they
/// hand to prospective clients; a signup/order carrying it attaches that customer
/// to this partner for life (see PartnerCustomer). `commissionRatePct` is the
/// lifetime rate; it is FROZEN onto each PartnerCommission row at accrual, so a
/// later rate change never rewrites already-earned commission.
model ReferralPartner {
  id                String              @id @default(cuid())
  // Optional login account the partner uses to view their portal at
  // /dashboard/partner. A partner may exist purely as an admin-managed record
  // (no login) until they self-serve. SetNull so deleting the user keeps history.
  userId            String?             @unique
  user              User?               @relation("PartnerAccount", fields: [userId], references: [id], onDelete: SetNull)
  name              String
  contactEmail      String?
  code              String              @unique
  // Lifetime commission rate (percent of the NET, pre-tax charge) earned on every
  // qualifying charge by every attached customer.
  commissionRatePct Float               @default(20)
  status            String              @default("ACTIVE") // ACTIVE | PAUSED
  notes             String?
  createdAt         DateTime            @default(now())
  customers         PartnerCustomer[]
  commissions       PartnerCommission[]
  payouts           PartnerPayout[]
  invites           PartnerInvite[]
  /// What KIND of partner this is: agency | kol | community | developer |
  /// reseller. Display only — the commission rate is `commissionRatePct` and
  /// is not derived from this. Null on partners linked before the field existed.
  type              String?
}

/// The durable link binding a referred customer to their referring partner for the
/// life of the account. `customerId` is UNIQUE: a customer is attached to exactly
/// ONE partner, permanently — the "lifetime attribution" guarantee.
model PartnerCustomer {
  id         String          @id @default(cuid())
  partnerId  String
  partner    ReferralPartner @relation(fields: [partnerId], references: [id], onDelete: Cascade)
  customerId String          @unique
  customer   User            @relation("PartnerAttachment", fields: [customerId], references: [id], onDelete: Cascade)
  attachedAt DateTime        @default(now())
  createdAt  DateTime        @default(now())
  // CREATOR PARTNER PROGRAM pricing (2026-09-26): null until this customer's
  // first-ever discounted (non-domain) purchase completes while attached — that
  // purchase is sold at PARTNER_FIRST_PURCHASE_PCT (50%) off, and every purchase
  // AFTER this timestamp is stamped sells at PARTNER_RECURRING_PCT (10%) off,
  // forever. See lib/partner-discount.ts. Claimed ATOMICALLY (an `updateMany`
  // guarded on this column being null, inside the same charge transaction that
  // debits the wallet / confirms the card charge) so two concurrent "first"
  // orders for the same customer can never both be sold at 50%.
  firstPurchaseDiscountUsedAt DateTime?

  @@index([partnerId])
}

/// One commission entry per qualifying charge. `invoiceId` is UNIQUE — this is the
/// idempotency guard: at most one commission row can ever exist per invoice, so a
/// retried/duplicated accrual (inline hook + background sweep) can never double-pay
/// a partner. `baseCents` and `ratePct` are snapshotted at accrual so the ledger is
/// a durable record independent of later rate changes.
model PartnerCommission {
  id          String          @id @default(cuid())
  partnerId   String
  partner     ReferralPartner @relation(fields: [partnerId], references: [id], onDelete: Cascade)
  customerId  String
  customer    User            @relation("PartnerCommissions", fields: [customerId], references: [id], onDelete: Cascade)
  invoiceId   String          @unique
  invoice     Invoice         @relation(fields: [invoiceId], references: [id], onDelete: Cascade)
  // Net (pre-tax) charge the commission was computed on, the frozen rate, and the
  // resulting commission — all snapshotted at accrual.
  baseCents   Int
  ratePct     Float
  amountCents Int
  kind        String          @default("CHARGE") // ORDER | RENEWAL | CHARGE
  status      String          @default("ACCRUED") // ACCRUED | PAID | VOID
  createdAt   DateTime        @default(now())
  paidAt      DateTime?

  @@index([partnerId, status])
  @@index([customerId])
}

/// A real payment made to a partner OFF-WALLET (bank transfer / Wise / PayPal /
/// invoice — see PartnerControls' payout form). Distinct from PartnerCommission
/// (what was EARNED): this is what was actually PAID, and can be a PARTIAL amount
/// ("$340 today even though $412 is accrued" — the owner's own example). A
/// partner's outstanding balance is therefore computed as
/// `sum(PartnerCommission, status != VOID) - sum(PartnerPayout)`, never by trying
/// to mark a fractional set of individual commission rows PAID. A FULL settlement
/// (adminSettlePartnerCommission) still flips every currently-ACCRUED commission
/// row to PAID for the per-row ledger display, AND records one PartnerPayout for
/// the same amount, so the two ledgers (earned vs. paid) always reconcile for the
/// common case; a PARTIAL payout (adminRecordPartnerPayout) only ever writes here
/// — the per-row commission ledger keeps showing ACCRUED until a later full
/// settlement, which is honest bookkeeping (accounting AR vs. a payments ledger),
/// not a bug.
model PartnerPayout {
  id            String          @id @default(cuid())
  partnerId     String
  partner       ReferralPartner @relation(fields: [partnerId], references: [id], onDelete: Cascade)
  amountCents   Int
  note          String?
  createdById   String?
  createdAt     DateTime        @default(now())

  @@index([partnerId, createdAt])
}

/// A pending invitation for a brand-new (non-customer) partner login — the admin
/// "create partner LOGINS" path (adminCreatePartnerAccount is the linked-by-email
/// path for an EXISTING account; this is for someone with no Nxeon account yet).
/// Mirrors OrgInvite's token/hash/expiry mechanics (lib/actions-teams.ts), but the
/// accept step must work for someone who is NOT signed in — it creates the
/// account. `tokenHash` (SHA-256 of the emailed token) is the only thing that
/// authorises; this row is display/cancel bookkeeping, same discipline as OrgInvite.
model PartnerInvite {
  id          String          @id @default(cuid())
  partnerId   String
  partner     ReferralPartner @relation(fields: [partnerId], references: [id], onDelete: Cascade)
  email       String
  tokenHash   String          @unique
  invitedById String?
  expiresAt   DateTime
  acceptedAt  DateTime?
  revokedAt   DateTime?
  createdAt   DateTime        @default(now())

  @@index([partnerId, createdAt])
}

// ---- Admin-managed testimonials (real social proof) ----
model Testimonial {
  id          String   @id @default(cuid())
  author      String
  role        String?
  quote       String
  avatarEmoji String?
  rating      Int      @default(5)
   * decides which messages a preference is even ALLOWED to suppress — a
   * declined payment, an imminent suspension or a 2FA change is delivered
   * whatever the customer ticked. Adding `notifyBilling` here would have been a
   * second store the send path never reads: exactly the defect that file was
   * written to fix, where a control reported success and governed nothing.
   */
  updatedAt       DateTime @updatedAt
}

/// One hit on a referral or partner link. The concept screens show a conversion
/// rate ("18.4% of 125 clicks") and a referral count over time; without a click
/// row there is no denominator and the figure cannot be shown honestly.
model ReferralClick {
  id              String   @id @default(cuid())
  /// The code from the link — User.referralCode or ReferralPartner.code.
  code            String
  /// Set once a signup is attributed to this click.
  convertedUserId String?
  ipHash          String?
  referer         String?
  createdAt       DateTime @default(now())

  @@index([code, createdAt])
}

/// An outstanding invitation to an organisation. The Team concept shows pending
/// invites with a role and an expiry, and states invites expire in 7 days.
model OrgInvite {
  id          String       @id @default(cuid())
  orgId       String
  org         Organization @relation(fields: [orgId], references: [id], onDelete: Cascade)
  email       String
  role        String       @default("MEMBER")
  /// SHA-256 of the accept token.
  tokenHash   String       @unique
  invitedById String?
  expiresAt   DateTime
