234	/**
235	 * Roll up a partner's standing: attached-customer count, lifetime commission
236	 * EARNED, and the real balance owed.
237	 *
238	 * `paidCents`/`outstandingCents` are computed from `PartnerPayout` — the ledger of
239	 * REAL payments made — not from summing PartnerCommission rows whose `status`
240	 * happens to read PAID. Two ledgers, "earned" (PartnerCommission) and "paid"
241	 * (PartnerPayout), net balance = earned − paid: the only way to honestly support
242	 * a PARTIAL payout ("$340 today even though $412 is accrued" — the owner's own
243	 * example) without inventing a way to mark a fractional set of commission rows
244	 * paid. A full settlement (adminSettlePartnerCommission) still flips every
245	 * ACCRUED row to PAID for the per-row ledger display, so for the common case the
246	 * two views agree; see PartnerPayout's own doc comment on the model.
247	 */
248	export async function computePartnerSummary(partnerId: string): Promise<PartnerSummary | null> {
249	  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
250	  if (!partner) return null;
251	
252	  const [customerCount, lifetimeAgg, payoutAgg] = await Promise.all([
253	    db.partnerCustomer.count({ where: { partnerId } }),
254	    db.partnerCommission.aggregate({
255	      where: { partnerId, status: { not: "VOID" } },
256	      _sum: { amountCents: true },
257	    }),
258	    db.partnerPayout.aggregate({
259	      where: { partnerId },
260	      _sum: { amountCents: true },
261	    }),
262	  ]);
263	
264	  const lifetimeCents = lifetimeAgg._sum.amountCents ?? 0;
265	  const paidCents = payoutAgg._sum.amountCents ?? 0;
266	  const outstandingCents = Math.max(0, lifetimeCents - paidCents);
267	  return {
268	    partnerId: partner.id,
269	    name: partner.name,
270	    code: partner.code,
271	    commissionRatePct: partner.commissionRatePct,
272	    status: partner.status,
273	    customerCount,
274	    lifetimeCents,
275	    outstandingCents,
276	    paidCents,
277	  };
278	}
