/**
 * Dependency-free, in-memory sliding-window rate limiter.
 *
 * Suitable for single-process app-level throttling (login attempts, etc).
 * State lives in a module-level Map; on a horizontally-scaled deployment each
 * instance limits independently — acceptable for auth-abuse mitigation. A
 * background sweep prunes empty buckets so the Map does not grow unbounded.
 */

type Bucket = number[]; // sorted-ish list of hit timestamps (ms)

const buckets = new Map<string, Bucket>();

// Persist the Map across HMR / route reloads in dev.
const globalForRl = globalThis as unknown as { __nxeonRateLimit?: Map<string, Bucket> };
const store: Map<string, Bucket> = globalForRl.__nxeonRateLimit ?? buckets;
if (process.env.NODE_ENV !== "production") globalForRl.__nxeonRateLimit = store;

export type RateLimitOptions = { max: number; windowMs: number };
export type RateLimitResult = { ok: boolean; retryAfterSec: number; remaining: number };

/**
 * The widest window any caller has ever asked for.
 *
 * The sweep below used a HARDCODED 15-minute horizon while callers pass windows
 * far longer than that — `RESEND_LIMIT` in lib/email-verification.ts is an hour,
 * as are the mail-send, calendar-mutation, org-invite and wallet-top-up limits.
 * A bucket whose last hit was 16 minutes ago was therefore DELETED, and deleting
 * a bucket resets its counter: "5 verification emails per hour" was really "5
 * per 15 minutes, forever", and "60 outbound mails per hour" was 60 per quarter
 * hour. The limiter silently enforced a limit nobody had chosen, and the longer
 * the window a caller asked for, the less of it was honoured.
 *
 * Tracking the real maximum keeps the sweep's only job — bounding the Map — from
 * quietly becoming a policy decision. It only ever grows, so it can never evict a
 * bucket that some caller still considers live.
 */
let widestWindowMs = 15 * 60 * 1000;

/**
 * Record and check a hit for `key`. Returns `{ ok, retryAfterSec, remaining }`.
 * When `ok` is false the caller should reject and surface `retryAfterSec`.
 */
export function checkRateLimit(key: string, { max, windowMs }: RateLimitOptions): RateLimitResult {
  const now = Date.now();
  if (windowMs > widestWindowMs) widestWindowMs = windowMs;
  sweep(now);
  const cutoff = now - windowMs;
  const hits = (store.get(key) ?? []).filter((t) => t > cutoff);

  if (hits.length >= max) {
    const oldest = hits[0];
    const retryAfterSec = Math.max(1, Math.ceil((oldest + windowMs - now) / 1000));
    store.set(key, hits); // persist the pruned window
    return { ok: false, retryAfterSec, remaining: 0 };
  }

  hits.push(now);

/* Dependency-free SVG charts, safe to render in server components. */

function pathFrom(points: [number, number][], smooth = true): string {
  if (points.length === 0) return "";
  if (!smooth || points.length < 3) {
    return points.map(([x, y], i) => `${i === 0 ? "M" : "L"}${x.toFixed(2)},${y.toFixed(2)}`).join(" ");
  }
  let d = `M${points[0][0].toFixed(2)},${points[0][1].toFixed(2)}`;
  for (let i = 1; i < points.length; i++) {
    const [x0, y0] = points[i - 1];
    const [x1, y1] = points[i];
    const cx = (x0 + x1) / 2;
    d += ` C${cx.toFixed(2)},${y0.toFixed(2)} ${cx.toFixed(2)},${y1.toFixed(2)} ${x1.toFixed(2)},${y1.toFixed(2)}`;
  }
  return d;
}

function scale(data: number[], w: number, h: number, pad = 2, max?: number): [number, number][] {
  const mx = max ?? Math.max(...data, 1e-9);
  const mn = 0;
  const n = Math.max(data.length - 1, 1);
  return data.map((v, i) => [
    (i / n) * (w - pad * 2) + pad,
    h - pad - ((v - mn) / (mx - mn || 1)) * (h - pad * 2),
  ]);
}

export function Sparkline({
  data,
  width = 120,
  height = 36,
  stroke = "#8a70fb",
  id,
}: {
  data: number[];
  width?: number;
  height?: number;
  stroke?: string;
  id: string;
}) {
  if (data.length === 0) return null;
  const pts = scale(data, width, height);
  const line = pathFrom(pts);
  const area = `${line} L${pts[pts.length - 1][0].toFixed(2)},${height} L${pts[0][0].toFixed(2)},${height} Z`;
  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} className="overflow-visible">
      <defs>
        <linearGradient id={`sg-${id}`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={stroke} stopOpacity="0.35" />
          <stop offset="100%" stopColor={stroke} stopOpacity="0" />
        </linearGradient>
      </defs>
      <path d={area} fill={`url(#sg-${id})`} />
      <path d={line} fill="none" stroke={stroke} strokeWidth="1.5" strokeLinecap="round" />
    </svg>
  );
}

export function AreaChart({
  series,
  width = 720,
  height = 220,
  id,
  yLabel,
  xLabels = [],
  maxY,
}: {
  series: { name: string; data: number[]; color: string }[];
  width?: number;
  height?: number;
  id: string;
  yLabel?: (v: number) => string;
  xLabels?: string[];
  maxY?: number;
}) {
  const all = series.flatMap((s) => s.data);
  if (all.length === 0) return <p className="text-sm text-slate-500">No data yet.</p>;
  const max = maxY ?? Math.max(...all, 1e-9);
  const padL = 46;
  const padB = 22;
  const cw = width - padL - 8;
  const ch = height - padB - 8;
  const gridLines = 4;

  return (
    <div className="w-full overflow-x-auto">
      <svg
        width="100%"
        viewBox={`0 0 ${width} ${height}`}
        preserveAspectRatio="none"
        className="min-w-[480px]"
        style={{ height }}
      >
        <defs>
          {series.map((s, si) => (
            <linearGradient key={si} id={`ag-${id}-${si}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={s.color} stopOpacity="0.30" />
              <stop offset="100%" stopColor={s.color} stopOpacity="0" />
            </linearGradient>
          ))}
        </defs>
        {Array.from({ length: gridLines + 1 }, (_, i) => {
          const y = 8 + (ch / gridLines) * i;
          const v = max * (1 - i / gridLines);
          return (
            <g key={i}>
              <line x1={padL} x2={width - 8} y1={y} y2={y} stroke="rgba(255,255,255,0.05)" />
              <text x={padL - 8} y={y + 3.5} textAnchor="end" fontSize="10" fill="#64748b">
                {yLabel ? yLabel(v) : v.toFixed(0)}
              </text>
            </g>
          );
        })}
        {xLabels.map((l, i) => (
          <text
            key={i}
            x={padL + (cw / Math.max(xLabels.length - 1, 1)) * i}
            y={height - 6}
            textAnchor="middle"
            fontSize="10"
            fill="#64748b"
          >
            {l}
          </text>
        ))}
        {series.map((s, si) => {
          const pts: [number, number][] = s.data.map((v, i) => [
            padL + (i / Math.max(s.data.length - 1, 1)) * cw,
            8 + ch - (v / max) * ch,
          ]);
          const line = pathFrom(pts);
          const area = `${line} L${(padL + cw).toFixed(2)},${8 + ch} L${padL},${8 + ch} Z`;
          return (
            <g key={si}>
              <path d={area} fill={`url(#ag-${id}-${si})`} />
              <path d={line} fill="none" stroke={s.color} strokeWidth="2" strokeLinecap="round" />
            </g>
          );
        })}
      </svg>
    </div>
  );
}

export function Donut({
  segments,
  size = 132,
  thickness = 14,
  centerLabel,
  centerSub,
}: {
  segments: { value: number; color: string }[];
  size?: number;
  thickness?: number;
  centerLabel?: string;
  centerSub?: string;
}) {
  const total = segments.reduce((n, s) => n + s.value, 0) || 1;
  const r = (size - thickness) / 2;
  const c = 2 * Math.PI * r;
  let offset = 0;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth={thickness} />
      {segments.map((s, i) => {
        const frac = s.value / total;
        const el = (
          <circle
            key={i}
            cx={size / 2}
            cy={size / 2}
            r={r}
            fill="none"
            stroke={s.color}
            strokeWidth={thickness}
            strokeLinecap="round"
            strokeDasharray={`${(frac * c).toFixed(2)} ${c.toFixed(2)}`}
            strokeDashoffset={(-offset * c).toFixed(2)}
            transform={`rotate(-90 ${size / 2} ${size / 2})`}
          />
        );
        offset += frac;
        return el;
      })}
      {centerLabel && (
        <text x="50%" y={centerSub ? "47%" : "52%"} textAnchor="middle" fontSize="20" fontWeight="700" fill="#f1f5f9">
          {centerLabel}
        </text>
      )}
      {centerSub && (
        <text x="50%" y="62%" textAnchor="middle" fontSize="10" fill="#64748b">
          {centerSub}
        </text>
      )}
    </svg>
  );
}

export function MeterBar({
  value,
  max,
  color = "#6f47f5",
  className = "",
}: {
