// Creator Partner Program — the partner's preferred (MANUAL) payout method.
//
// Pure, DB-free, and safe to import from client components: the method list,
// the zod schemas the server action validates against, and the masking used
// to show a partner their saved details without echoing them back in full.
//
// Payouts are NOT automated. An admin pays by hand (PayPal / Wise / bank /
// crypto) and records it as a PartnerPayout on /admin/partners/<id>. This
// only records WHERE the partner would like that money sent. Storage lives in
// PartnerPayoutProfile (prisma/schema.prisma); the details + note are sealed
// with lib/crypto-box.ts before they touch the database (see
// lib/actions-partner-profile.ts). Nothing in this file ever logs a value.

import { z } from "zod";

export const PAYOUT_METHODS = [
  { key: "PAYPAL", label: "PayPal", blurb: "Sent to your PayPal account email." },
  { key: "WISE", label: "Wise", blurb: "Sent to the email on your Wise account." },
  { key: "BANK", label: "Bank transfer", blurb: "Direct deposit — IBAN/SWIFT or account/routing number." },
  { key: "CRYPTO", label: "Crypto", blurb: "Stablecoin or coin to a wallet address you control." },
] as const;

export type PayoutMethodKey = (typeof PAYOUT_METHODS)[number]["key"];

export function payoutMethodLabel(key: string | null | undefined): string | null {
  return PAYOUT_METHODS.find((m) => m.key === key)?.label ?? null;
}

export const CRYPTO_NETWORKS = [
  "Bitcoin",
  "Ethereum (ERC-20)",
  "Tron (TRC-20)",
  "Solana",
  "Polygon",
  "BNB Smart Chain (BEP-20)",
  "Arbitrum",
  "Base",
] as const;

const trimmed = (max: number) => z.string().trim().max(max);
const optional = (max: number) =>
  z.string().trim().max(max).optional().transform((v) => (v ? v : undefined));

/** Contact details — every field optional except that name/email must be sane if given. */
export const contactSchema = z.object({
  contactName: optional(120),
  contactEmail: z
    .string()
    .trim()
    .max(200)
    .optional()
    .transform((v) => (v ? v : undefined))
    .pipe(z.email("Enter a valid contact email.").optional()),
  phone: optional(40).pipe(
    z.string().regex(/^[+()0-9 .-]{5,40}$/, "Phone can only contain digits, spaces, +, ( ), . and -.").optional()
  ),
  discord: optional(64),
  social: optional(200),
});
export type ContactInput = z.input<typeof contactSchema>;

const note = optional(500);

/** Method-specific payout details. `method` picks which fields are required. */
export const payoutSchema = z.discriminatedUnion("method", [
  z.object({
