      iban: optional(42).transform((v) => v?.replace(/\s+/g, "").toUpperCase()),
      swift: optional(11).transform((v) => v?.replace(/\s+/g, "").toUpperCase()),
      accountNumber: optional(34).transform((v) => v?.replace(/\s+/g, "")),
      routingNumber: optional(20).transform((v) => v?.replace(/\s+/g, "")),
      note,
    })
    .superRefine((v, ctx) => {
