// Server-only read side of PartnerPayoutProfile: decrypt the sealed payout
// details. Deliberately NOT a "use server" file (every export of one is a
// network-callable endpoint) — only server components / actions import this.
//
// Two readers, two shapes:
//  - the partner themselves  -> `partnerPayoutView`: contact fields + a MASKED
//    one-line summary. The full details never go back to the browser, so a
//    hijacked session can't read a bank account off the page.
//  - billing-area admins     -> `adminPayoutView`: every field, decrypted, so
//    whoever pays knows exactly where to send it.

import { db } from "./db";
import { decryptSecret } from "./crypto-box";
import { payoutSchema, maskedPayoutSummary, payoutDetailRows, payoutMethodLabel, type PayoutDetails } from "./partner-payout";

function openDetails(enc: string | null | undefined): PayoutDetails | null {
  const raw = decryptSecret(enc);
  if (!raw) return null;
  try {
    const parsed = payoutSchema.safeParse(JSON.parse(raw));
    return parsed.success ? parsed.data : null;
  } catch {
    return null;
  }
}

export type PartnerContact = {
  contactName: string;
  contactEmail: string;
  phone: string;
  discord: string;
  social: string;
};

export type PartnerPayoutView = {
  contact: PartnerContact;
  method: string | null;
  methodLabel: string | null;
  /** Masked one-liner, e.g. "PayPal · j•••@gmail.com". Null when nothing saved. */
  summary: string | null;
  hasNote: boolean;
  updatedAt: string | null;
};

export async function partnerPayoutView(partnerId: string): Promise<PartnerPayoutView> {
  const p = await db.partnerPayoutProfile.findUnique({ where: { partnerId } });
  const details = openDetails(p?.payoutDetailsEnc);
  return {
    contact: {
      contactName: p?.contactName ?? "",
      contactEmail: p?.contactEmail ?? "",
      phone: p?.phone ?? "",
      discord: p?.discord ?? "",
      social: p?.social ?? "",
    },
    method: details ? details.method : null,
    methodLabel: details ? payoutMethodLabel(details.method) : null,
    summary: details ? maskedPayoutSummary(details) : null,
    hasNote: !!details?.note,
    updatedAt: p?.payoutUpdatedAt?.toISOString() ?? null,
  };
}

export type AdminPayoutView = {
  contact: PartnerContact;
  methodLabel: string | null;
  rows: { label: string; value: string }[];
  note: string | null;
  updatedAt: Date | null;
  /** True when a row exists but its details couldn't be decrypted (AUTH_SECRET changed / tampered). */
  unreadable: boolean;
};

export async function adminPayoutView(partnerId: string): Promise<AdminPayoutView | null> {
  const p = await db.partnerPayoutProfile.findUnique({ where: { partnerId } });
  if (!p) return null;
  const details = openDetails(p.payoutDetailsEnc);
  return {
    contact: {
      contactName: p.contactName ?? "",
      contactEmail: p.contactEmail ?? "",
      phone: p.phone ?? "",
      discord: p.discord ?? "",
      social: p.social ?? "",
    },
    methodLabel: details ? payoutMethodLabel(details.method) : null,
    rows: details ? payoutDetailRows(details) : [],
    note: details?.note ?? null,
    updatedAt: p.payoutUpdatedAt,
    unreadable: !!p.payoutDetailsEnc && !details,
  };
}

