"use server";

// Creator Partner Program — the partner's own Settings tab
// (/dashboard/partner?tab=settings): contact details + preferred payout method.
//
// Ownership: the partner row is ALWAYS resolved from the signed-in user
// (ReferralPartner.userId is unique). No partner id is ever accepted from the
// client, so a partner can only ever edit their own profile.
//
// Payout details are sealed with lib/crypto-box.ts before being written and
// are never logged — the audit row records only THAT the method changed and
// to which method type. Payouts themselves stay manual (see lib/partner-payout.ts).

import { revalidatePath } from "next/cache";
import { headers } from "next/headers";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { checkRateLimit, clientIp } from "./rate-limit";
import { encryptSecret } from "./crypto-box";
import { sendMail } from "./mailer";
import { contactSchema, payoutSchema, payoutMethodLabel } from "./partner-payout";

export type PartnerSettingsState = { ok?: boolean; error?: string; fieldErrors?: Record<string, string> };

const RL = { max: 10, windowMs: 10 * 60 * 1000 };

async function ownPartner() {
  const user = await requireUser();
  const partner = await db.referralPartner.findUnique({ where: { userId: user.id }, select: { id: true } });
  return { user, partner };
}

function str(fd: FormData, key: string): string | undefined {
  const v = fd.get(key);
  return typeof v === "string" ? v : undefined;
}

function firstErrors(issues: { path: PropertyKey[]; message: string }[]): Record<string, string> {
  const out: Record<string, string> = {};
  for (const i of issues) {
    const k = String(i.path[0] ?? "_");
    if (!out[k]) out[k] = i.message;
  }
  return out;
}

async function limited(userId: string): Promise<string | null> {
  const ip = clientIp(await headers());
  const rl = checkRateLimit(`partner-settings:${userId}:${ip}`, RL);
  return rl.ok ? null : `Too many changes in a short time. Try again in ${rl.retryAfterSec}s.`;
}

export async function savePartnerContact(_prev: PartnerSettingsState, fd: FormData): Promise<PartnerSettingsState> {
  const { user, partner } = await ownPartner();
  if (!partner) return { error: "This account isn't linked to a partner profile." };
  const rl = await limited(user.id);
  if (rl) return { error: rl };

  const parsed = contactSchema.safeParse({
    contactName: str(fd, "contactName"),
    contactEmail: str(fd, "contactEmail"),
    phone: str(fd, "phone"),
    discord: str(fd, "discord"),
    social: str(fd, "social"),
  });
  if (!parsed.success) {
    const fieldErrors = firstErrors(parsed.error.issues);
    return { error: Object.values(fieldErrors)[0], fieldErrors };
  }
  const c = parsed.data;
  const data = {
    contactName: c.contactName ?? null,
    contactEmail: c.contactEmail ?? null,
    phone: c.phone ?? null,
    discord: c.discord ?? null,
    social: c.social ?? null,
  };
  await db.partnerPayoutProfile.upsert({
    where: { partnerId: partner.id },
    create: { partnerId: partner.id, ...data },
    update: data,
  });
  await db.auditLog.create({ data: { userId: user.id, action: "partner.contact_update" } });
  revalidatePath("/dashboard/partner");
  return { ok: true };
}

export async function savePartnerPayoutMethod(_prev: PartnerSettingsState, fd: FormData): Promise<PartnerSettingsState> {
  // A payout destination is where real money goes — never changeable by an
  // admin acting as the partner. The partner sets it themselves.
  try {
    await assertNotImpersonating();
  } catch (e) {
    return { error: (e as Error).message };
  }
  const { user, partner } = await ownPartner();
  if (!partner) return { error: "This account isn't linked to a partner profile." };
  const rl = await limited(user.id);
  if (rl) return { error: rl };

  const method = str(fd, "method");
  const parsed = payoutSchema.safeParse({
    method,
    paypalEmail: str(fd, "paypalEmail"),
    wiseEmail: str(fd, "wiseEmail"),
    accountHolder: str(fd, "accountHolder"),
    accountName: str(fd, "accountName"),
    bankName: str(fd, "bankName"),
    country: str(fd, "country"),
    iban: str(fd, "iban"),
    swift: str(fd, "swift"),
    accountNumber: str(fd, "accountNumber"),
    routingNumber: str(fd, "routingNumber"),
    network: str(fd, "network"),
    asset: str(fd, "asset"),
    walletAddress: str(fd, "walletAddress"),
    note: str(fd, "note"),
  });
  if (!parsed.success) {
    const fieldErrors = firstErrors(parsed.error.issues);
    if (fieldErrors.method) return { error: "Choose a payout method.", fieldErrors };
    return { error: Object.values(fieldErrors)[0], fieldErrors };
  }

  // Only the fields of the chosen method survive the discriminated union, so
  // switching from BANK to PAYPAL can't leave stale bank numbers sealed inside.
  const sealed = encryptSecret(JSON.stringify(parsed.data));
  const now = new Date();
  await db.partnerPayoutProfile.upsert({
    where: { partnerId: partner.id },
    create: { partnerId: partner.id, payoutMethod: parsed.data.method, payoutDetailsEnc: sealed, payoutUpdatedAt: now },
    update: { payoutMethod: parsed.data.method, payoutDetailsEnc: sealed, payoutUpdatedAt: now },
  });
  await db.auditLog.create({
    data: { userId: user.id, action: "partner.payout_method_update", detail: `method=${parsed.data.method}` },
  });

  // Security notice to the account's own email — if this wasn't them, they
  // hear about it before anyone is paid. Best-effort; the save already stands.
  try {
    const label = payoutMethodLabel(parsed.data.method) ?? parsed.data.method;
    await sendMail({
      to: user.email,
      userId: user.id,
      kind: "security_change",
      template: "partner_payout_changed",
      subject: "Your Nxeon partner payout details were changed",
      html:
        `<p>Hi${user.name ? ` ${escapeHtml(user.name)}` : ""},</p>` +
