// Creator Partner Program — date-ranged analytics for the partner's own
// Analytics tab (/dashboard/partner?tab=analytics). Server-only.
//
// Every figure is a count or sum off a real table; nothing is estimated:
//   clicks      ReferralClick   (code = partner.code) — app/partner/[code]/route.ts
//   signups     PartnerCustomer (partnerId, attachedAt) — the permanent attachment
//   conversions a customer's FIRST non-void PartnerCommission — their first paid,
//               commissionable purchase (lib/partner-commission.ts accrues one row
//               per qualifying invoice)
//   commission  PartnerCommission rows (amountCents, status ACCRUED | PAID | VOID)
//   payouts     PartnerPayout rows — real off-wallet payments the admin recorded
//
// Dates are bucketed in UTC.

import { db } from "./db";

export const RANGE_KEYS = ["7d", "30d", "90d", "12m", "all", "custom"] as const;
export type RangeKey = (typeof RANGE_KEYS)[number];
export type Bucket = "day" | "week" | "month";

export type ResolvedRange = {
  key: RangeKey;
  from: Date; // inclusive
  to: Date; // exclusive
  bucket: Bucket;
  /** YYYY-MM-DD, inclusive end — for the custom picker's inputs. */
  fromDay: string;
  toDay: string;
  error?: string;
};

const DAY = 86_400_000;

function startOfUtcDay(d: Date): Date {
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
}
function ymd(d: Date): string {
  return d.toISOString().slice(0, 10);
}
function parseDay(s: string | undefined): Date | null {
  if (!s || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
  const d = new Date(`${s}T00:00:00Z`);
  return Number.isNaN(d.getTime()) ? null : d;
}

function bucketFor(spanMs: number): Bucket {
  const days = spanMs / DAY;
  if (days <= 45) return "day";
  if (days <= 200) return "week";
  return "month";
}

/**
 * Turn `?range=&from=&to=` into a concrete [from, to) window. `earliest` is the
 * partner's first recorded activity, used as the start of "all time".
 * An unreadable custom range falls back to 30 days and says why.
 */
export function resolveRange(
  q: { range?: string; from?: string; to?: string },
  earliest: Date,
  now = new Date()
): ResolvedRange {
  const todayEnd = new Date(startOfUtcDay(now).getTime() + DAY);
  const key = (RANGE_KEYS as readonly string[]).includes(q.range ?? "") ? (q.range as RangeKey) : "30d";

  const make = (k: RangeKey, from: Date, to: Date, error?: string): ResolvedRange => ({
    key: k,
    from,
    to,
    bucket: bucketFor(to.getTime() - from.getTime()),
    fromDay: ymd(from),
    toDay: ymd(new Date(to.getTime() - DAY)),
    error,
  });
  const lastDays = (n: number) => new Date(todayEnd.getTime() - n * DAY);

  switch (key) {
    case "7d":
      return make(key, lastDays(7), todayEnd);
    case "90d":
      return make(key, lastDays(90), todayEnd);
    case "12m": {
      const f = startOfUtcDay(now);
      f.setUTCFullYear(f.getUTCFullYear() - 1);
      return make(key, new Date(f.getTime() + DAY), todayEnd);
    }
    case "all": {
      const f = startOfUtcDay(earliest);
      // At least a week, so a brand-new partner's chart isn't a single bar.
      return make(key, f.getTime() > lastDays(7).getTime() ? lastDays(7) : f, todayEnd);
    }
    case "custom": {
      const f = parseDay(q.from);
      const t = parseDay(q.to);
      if (!f || !t) return make("30d", lastDays(30), todayEnd, "Pick both a start and an end date.");
      if (f.getTime() > t.getTime()) return make("30d", lastDays(30), todayEnd, "The start date is after the end date.");
      const end = new Date(Math.min(t.getTime() + DAY, todayEnd.getTime()));
      if (end.getTime() - f.getTime() > 5 * 366 * DAY) return make("30d", lastDays(30), todayEnd, "Custom ranges can span at most five years.");
      if (f.getTime() >= todayEnd.getTime()) return make("30d", lastDays(30), todayEnd, "That range is in the future.");
      return make("custom", f, end);
    }
    default:
      return make("30d", lastDays(30), todayEnd);
  }
}

function bucketStart(d: Date, b: Bucket): Date {
  const day = startOfUtcDay(d);
  if (b === "day") return day;
  if (b === "week") {
    const dow = (day.getUTCDay() + 6) % 7; // Monday = 0
    return new Date(day.getTime() - dow * DAY);
  }
  return new Date(Date.UTC(day.getUTCFullYear(), day.getUTCMonth(), 1));
}
function nextBucket(d: Date, b: Bucket): Date {
  if (b === "day") return new Date(d.getTime() + DAY);
  if (b === "week") return new Date(d.getTime() + 7 * DAY);
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 1));
}

/** Every bucket start covering [from, to), in order. */
function bucketKeys(r: ResolvedRange): Date[] {
  const out: Date[] = [];
  for (let d = bucketStart(r.from, r.bucket); d.getTime() < r.to.getTime(); d = nextBucket(d, r.bucket)) {
    out.push(d);
    if (out.length > 400) break; // hard stop — month buckets over 5y is 61
  }
  return out;
}

/**
 * A product LABEL for a commission row, derived from the invoice description
 * WITHOUT exposing the customer's own identifiers. Descriptions carry server
 * hostnames and domains ("Pro VPS (studionexis-soul) — Monthly", "Business
 * Email renewal: Starter for example.com") — a partner sees the kind of
 * product, never their customer's server or domain name.
 */
export function productLabel(description: string): string {
  const d = description.replace(/^renewal:\s*/i, "").trim();
  const low = d.toLowerCase();
  if (low.includes("game server") || /^renewal:.*slots|players/i.test(description)) {
    const game = d.split(/\s+—\s+/)[0]?.trim();
    return game && game.length <= 40 ? `Game server · ${game}` : "Game server";
  }
  if (low.includes("business email") || low.includes("mailbox")) return "Business email";
  if (low.includes("domain")) return "Domain";
  if (low.includes("hosting")) return "Web hosting";
  if (low.includes("extra disk") || low.includes("storage")) return "Extra storage";
  if (low.includes("backup")) return "Backups";
  if (low.includes("dedicated ip")) return "Dedicated IP";
  if (low.includes("vps") || low.includes("vcpu")) {
    const plan = d.split(/\s*\(/)[0]?.trim();
    return plan && plan.length <= 40 && /vps/i.test(plan) ? plan : "VPS";
  }
  return "Other service";
}

export type SeriesPoint = { t: string; label: string; clicks: number; signups: number; conversions: number; commissionCents: number };

export type PartnerAnalytics = {
  range: ResolvedRange extends infer R ? Omit<R & object, "from" | "to"> & { from: string; to: string } : never;
  totals: {
    clicks: number;
    clicksLedToSignup: number;
    signups: number;
    conversions: number;
    signupsInRangeWhoPaid: number;
    commissionCents: number;
    accruedCents: number;
    paidRowCents: number;
    voidCents: number;
    payoutsCents: number;
    charges: number;
  };
  series: SeriesPoint[];
  sources: { source: string; clicks: number; signups: number }[];
  events: {
    id: string;
    when: string;
    customer: string;
    product: string;
    kind: string;
    baseCents: number;
    amountCents: number;
    status: string;
  }[];
  eventsTruncated: boolean;
};

const EVENTS_LIMIT = 300;

function sourceOf(referer: string | null): string {
  if (!referer) return "Direct / not shared";
  try {
    const host = new URL(referer).hostname.replace(/^www\./, "").replace(/^m\./, "");
    return host || "Direct / not shared";
  } catch {
    return "Direct / not shared";
  }
}

function label(d: Date, b: Bucket): string {
  if (b === "month") return d.toLocaleDateString("en-US", { month: "short", year: "2-digit", timeZone: "UTC" });
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
}

export async function partnerEarliestActivity(partner: { id: string; code: string; createdAt: Date }): Promise<Date> {
  const [click, attach] = await Promise.all([
    db.referralClick.findFirst({ where: { code: partner.code }, orderBy: { createdAt: "asc" }, select: { createdAt: true } }),
    db.partnerCustomer.findFirst({ where: { partnerId: partner.id }, orderBy: { attachedAt: "asc" }, select: { attachedAt: true } }),
  ]);
  return new Date(
    Math.min(partner.createdAt.getTime(), click?.createdAt.getTime() ?? Infinity, attach?.attachedAt.getTime() ?? Infinity)
  );
}

export async function computePartnerAnalytics(
  partner: { id: string; code: string },
  r: ResolvedRange
): Promise<PartnerAnalytics> {
  const inRange = { gte: r.from, lt: r.to };
  const [clicks, signups, firstCommissions, commissionRows, statusSums, payouts, events] = await Promise.all([
    db.referralClick.findMany({
      where: { code: partner.code, createdAt: inRange },
      select: { createdAt: true, referer: true, convertedUserId: true },
      take: 100_000,
    }),
    db.partnerCustomer.findMany({
      where: { partnerId: partner.id, attachedAt: inRange },
      select: { attachedAt: true, customerId: true },
    }),
    // Each attached customer's first non-void commission = their first paid purchase.
    db.partnerCommission.groupBy({
      by: ["customerId"],
      where: { partnerId: partner.id, status: { not: "VOID" } },
      _min: { createdAt: true },
    }),
    db.partnerCommission.findMany({
      where: { partnerId: partner.id, createdAt: inRange, status: { not: "VOID" } },
      select: { createdAt: true, amountCents: true },
    }),
    db.partnerCommission.groupBy({
      by: ["status"],
      where: { partnerId: partner.id, createdAt: inRange },
      _sum: { amountCents: true },
      _count: { _all: true },
    }),
    db.partnerPayout.aggregate({ where: { partnerId: partner.id, createdAt: inRange }, _sum: { amountCents: true } }),
    db.partnerCommission.findMany({
      where: { partnerId: partner.id, createdAt: inRange },
      orderBy: { createdAt: "desc" },
      take: EVENTS_LIMIT + 1,
      select: {
        id: true,
        createdAt: true,
        kind: true,
        baseCents: true,
        amountCents: true,
        status: true,
        customer: { select: { name: true, email: true } },
        invoice: { select: { description: true } },
      },
    }),
  ]);

  const conversionsInRange = firstCommissions
    .map((c) => c._min.createdAt)
    .filter((d): d is Date => !!d && d >= r.from && d < r.to);
  const paidCustomers = new Set(firstCommissions.map((c) => c.customerId));

  // ---- time series ----
  const keys = bucketKeys(r);
  const idx = new Map(keys.map((k, i) => [k.getTime(), i]));
  const series: SeriesPoint[] = keys.map((k) => ({
    t: k.toISOString(),
    label: label(k, r.bucket),
    clicks: 0,
    signups: 0,
    conversions: 0,
    commissionCents: 0,
  }));
  const at = (d: Date) => idx.get(bucketStart(d, r.bucket).getTime());
  for (const c of clicks) { const i = at(c.createdAt); if (i !== undefined) series[i].clicks++; }
  for (const s of signups) { const i = at(s.attachedAt); if (i !== undefined) series[i].signups++; }
  for (const d of conversionsInRange) { const i = at(d); if (i !== undefined) series[i].conversions++; }
  for (const c of commissionRows) { const i = at(c.createdAt); if (i !== undefined) series[i].commissionCents += c.amountCents; }

  // ---- sources (referer host) ----
  const src = new Map<string, { clicks: number; signups: number }>();
  for (const c of clicks) {
    const k = sourceOf(c.referer);
    const e = src.get(k) ?? { clicks: 0, signups: 0 };
    e.clicks++;
    if (c.convertedUserId) e.signups++;
    src.set(k, e);
  }
  const sources = [...src.entries()]
    .map(([source, v]) => ({ source, ...v }))
    .sort((a, b) => b.clicks - a.clicks)
    .slice(0, 10);

  const sum = (status: string) => statusSums.find((s) => s.status === status)?._sum.amountCents ?? 0;
  const accruedCents = sum("ACCRUED");
  const paidRowCents = sum("PAID");

  return {
    range: { ...r, from: r.from.toISOString(), to: r.to.toISOString() },
    totals: {
      clicks: clicks.length,
      clicksLedToSignup: clicks.filter((c) => c.convertedUserId).length,
      signups: signups.length,
      conversions: conversionsInRange.length,
      signupsInRangeWhoPaid: signups.filter((s) => paidCustomers.has(s.customerId)).length,
      commissionCents: accruedCents + paidRowCents,
      accruedCents,
      paidRowCents,
      voidCents: sum("VOID"),
      payoutsCents: payouts._sum.amountCents ?? 0,
      charges: statusSums.filter((s) => s.status !== "VOID").reduce((n, s) => n + s._count._all, 0),
    },
    series,
    sources,
    events: events.slice(0, EVENTS_LIMIT).map((e) => ({
      id: e.id,
      when: e.createdAt.toISOString(),
      // Same identifier the page has always shown for a commission row.
      customer: e.customer.name || e.customer.email,
      product: productLabel(e.invoice.description),
      kind: e.kind,
      baseCents: e.baseCents,
      amountCents: e.amountCents,
      status: e.status,
    })),
    eventsTruncated: events.length > EVENTS_LIMIT,
  };
}

