// Creator Partner Program — files that are for PARTNERS only (not public/).
//
// The program terms PDF is served through an authenticated route
// (app/api/creator-partner/terms/route.ts) rather than from public/: it is a
// document for signed-in partners, and it must only appear once the owner has
// approved a version that matches what the platform actually does (see the
// Terms tab and docs/DOCUMENTATION.md "Creator Partner Program").
//
// It lives OUTSIDE the repo and the build — same env-override-with-prod-default
// pattern as BOARD_UPLOAD_DIR (lib/board-shared.ts) — so publishing or
// replacing it is a file copy, not a deploy:
//   install -o nxeon -m 0644 approved.pdf /opt/nxeon/partner-files/creator-partner-terms.pdf
// No file there = no download button (the Terms tab still shows the terms).

import { promises as fs } from "node:fs";
import { join } from "node:path";

export const PARTNER_FILES_DIR = process.env.NXEON_PARTNER_FILES_DIR ?? "/opt/nxeon/partner-files";
export const PARTNER_TERMS_PDF = join(PARTNER_FILES_DIR, "creator-partner-terms.pdf");

/** Size + mtime of the published terms PDF, or null when none is published. */
export async function partnerTermsPdfInfo(): Promise<{ sizeBytes: number; updatedAt: string } | null> {
  try {
    const st = await fs.stat(PARTNER_TERMS_PDF);
    if (!st.isFile() || st.size === 0) return null;
    return { sizeBytes: st.size, updatedAt: st.mtime.toISOString() };
  } catch {
    return null;
  }
}
EOF
cat > /root/nxeon-worktrees/partner-tabs/app/api/creator-partner/terms/route.ts <<'EOF'
import { promises as fs } from "node:fs";
import { NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { PARTNER_TERMS_PDF } from "@/lib/partner-files";

export const dynamic = "force-dynamic";

/**
 * The Creator Partner Program terms PDF — partners (and admins) only.
 * Not in public/: see lib/partner-files.ts for why and where the file lives.
 * 404 (not 403) for a signed-in non-partner, so the route doesn't advertise
 * itself; 404 too when no approved PDF has been published.
 */
export async function GET() {
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "Sign in first." }, { status: 401 });
  if (user.role !== "ADMIN") {
    const partner = await db.referralPartner.findUnique({ where: { userId: user.id }, select: { id: true } });
    if (!partner) return NextResponse.json({ error: "Not found" }, { status: 404 });
  }
  let buf: Buffer;
  try {
    buf = await fs.readFile(PARTNER_TERMS_PDF);
  } catch {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }
  // Refuse to serve anything that isn't actually a PDF, whatever was copied there.
  if (buf.subarray(0, 5).toString("latin1") !== "%PDF-") {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }
  return new NextResponse(new Uint8Array(buf), {
    headers: {
      "content-type": "application/pdf",
      "content-disposition": 'attachment; filename="Nxeon-Creator-Partner-Terms.pdf"',
      "cache-control": "private, no-store",
      "x-content-type-options": "nosniff",
    },
  });
}
EOF

