"use client";

/* Dependency-free SVG bar chart with a hover/focus tooltip — the interactive
 * sibling of the server-safe charts in ./charts.tsx (no chart library, per
 * CLAUDE.md). A client component only because it measures its own width, so
 * axis text stays at its real pixel size on a phone instead of being scaled
 * down with a fixed viewBox, and because the tooltip follows the pointer.
 *
 * One series per chart, one y-axis. Colours are CSS custom properties, so the
 * Nexion light/dark scopes (app/globals.css) re-tint it with no extra code.
 */

import { useEffect, useRef, useState } from "react";

export type BarDatum = { label: string; value: number; /** Tooltip heading; defaults to label. */ title?: string };

function niceMax(max: number, integer: boolean): { top: number; step: number } {
  if (max <= 0) return { top: integer ? 4 : 1, step: integer ? 1 : 0.25 };
  const rough = max / 4;
  const pow = Math.pow(10, Math.floor(Math.log10(rough)));
  const n = rough / pow;
  let step = (n <= 1 ? 1 : n <= 2 ? 2 : n <= 2.5 ? 2.5 : n <= 5 ? 5 : 10) * pow;
  if (integer) step = Math.max(1, Math.ceil(step));
  return { top: step * Math.ceil(max / step), step };
}

export function BarChart({
  data,
  height = 190,
  color = "var(--color-cyan)",
  format = (v: number) => v.toLocaleString("en-US"),
  integer = true,
  ariaLabel,
  unit = "",
}: {
  data: BarDatum[];
  height?: number;
  color?: string;
  /** Formats y-axis ticks and the tooltip value. */
  format?: (v: number) => string;
  /** Integer-only ticks (counts). False for money. */
  integer?: boolean;
  ariaLabel: string;
  /** Appended to the tooltip value, e.g. " clicks". */
  unit?: string;
}) {
  const wrap = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(640);
  const [hover, setHover] = useState<number | null>(null);

  useEffect(() => {
    const el = wrap.current;
    if (!el) return;
    const ro = new ResizeObserver((entries) => {
      const w = Math.round(entries[0].contentRect.width);
      if (w > 0) setWidth(w);
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const max = Math.max(0, ...data.map((d) => d.value));
  const { top, step } = niceMax(max, integer);
  const ticks: number[] = [];
  for (let v = 0; v <= top + 1e-9; v += step) ticks.push(v);
  const tickText = ticks.map(format);
  const padL = Math.max(24, Math.max(...tickText.map((t) => t.length)) * 6.4 + 10);
  const padR = 6;
  const padT = 10;
  const padB = 24;
  const cw = Math.max(10, width - padL - padR);
  const ch = height - padT - padB;
  const n = Math.max(1, data.length);
  const slot = cw / n;
  const barW = Math.max(1, Math.min(slot - 2, 26)); // 2px surface gap between neighbours
  const y = (v: number) => padT + ch - (v / top) * ch;
  const every = Math.max(1, Math.ceil(n / Math.max(1, Math.floor(cw / 58))));

  const onKey = (e: React.KeyboardEvent) => {
    if (!data.length) return;
    if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
      e.preventDefault();
      const cur = hover ?? (e.key === "ArrowRight" ? -1 : data.length);
      setHover(Math.max(0, Math.min(data.length - 1, cur + (e.key === "ArrowRight" ? 1 : -1))));
    } else if (e.key === "Escape") setHover(null);
  };

  const h = hover !== null ? data[hover] : null;
  const hx = hover !== null ? padL + slot * hover + slot / 2 : 0;

  return (
    <div
      ref={wrap}
      className="relative w-full outline-none focus-visible:ring-2 focus-visible:ring-[#2f7eef]/60 rounded-[8px]"
      tabIndex={0}
      role="img"
      aria-label={ariaLabel}
      onKeyDown={onKey}
      onBlur={() => setHover(null)}
      onMouseLeave={() => setHover(null)}
    >
      <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} className="block" aria-hidden>
        {ticks.map((t, i) => (
          <g key={i}>
            <line x1={padL} x2={width - padR} y1={y(t)} y2={y(t)} stroke="var(--color-rim-soft)" strokeWidth={1} />
            <text x={padL - 8} y={y(t) + 3.5} textAnchor="end" fontSize="10.5" fill="var(--color-tx-faint)">
              {tickText[i]}
            </text>
          </g>
        ))}
        {hover !== null && (
          <rect x={padL + slot * hover} y={padT} width={slot} height={ch} fill="var(--color-rim-soft)" opacity={0.7} />
        )}
        {data.map((d, i) => {
          const x = padL + slot * i + (slot - barW) / 2;
          const bh = Math.max(0, y(0) - y(d.value));
          if (bh <= 0) return null;
          const r = Math.min(4, barW / 2, bh);
          const yt = y(d.value);
          // Rounded data-end (top), square at the baseline.
          const path = `M${x},${y(0)} V${yt + r} Q${x},${yt} ${x + r},${yt} H${x + barW - r} Q${x + barW},${yt} ${x + barW},${yt + r} V${y(0)} Z`;
          return <path key={i} d={path} fill={color} opacity={hover === null || hover === i ? 1 : 0.55} />;
        })}
        <line x1={padL} x2={width - padR} y1={y(0)} y2={y(0)} stroke="var(--color-rim-hi)" strokeWidth={1} />
        {data.map((d, i) =>
          i % every === 0 ? (
            <text key={i} x={padL + slot * i + slot / 2} y={height - 7} textAnchor="middle" fontSize="10.5" fill="var(--color-tx-faint)">
              {d.label}
            </text>
          ) : null
        )}
        {/* Hit targets: the whole column, not just the bar — a 0-value day is still hoverable. */}
        {data.map((_, i) => (
          <rect key={i} x={padL + slot * i} y={padT} width={slot} height={ch} fill="transparent" onMouseEnter={() => setHover(i)} />
        ))}
      </svg>
      {h && (
        <div
          className="pointer-events-none absolute top-0 z-10 -translate-x-1/2 whitespace-nowrap rounded-[9px] border border-rim-hi bg-[rgba(4,11,30,.94)] px-2.5 py-1.5 text-[11.5px] shadow-lg"
          style={{ left: Math.min(Math.max(hx, 70), width - 70) }}
        >
          <div className="text-tx-faint">{h.title ?? h.label}</div>
          <div className="num text-[13px] text-white">
            {format(h.value)}
            {unit}
          </div>
        </div>
      )}
    </div>
  );
}

