/* ── Already a partner ─────────────────────────────────────────────────── */
function PartnerDashboard({ partner, initialTab }: { partner: PartnerInfo; initialTab: PartnerTab }) {
  const sp = useSearchParams();
  // The URL is the source of truth once hydrated (back/forward, a range
  // change's router.push); `initialTab` is the server's own reading of the
  // same URL, so first paint and hydration agree.
  const fromUrl = sp.get("tab");
  const tab: PartnerTab = isPartnerTab(fromUrl) ? fromUrl : fromUrl === null ? initialTab : "overview";
  const tier = tierFor(partner.ratePct);
  const typeName = PARTNER_TYPES.find((t) => t.key === partner.type)?.name ?? partner.type;
  const tabRefs = useRef<Partial<Record<PartnerTab, HTMLButtonElement | null>>>({});

  const select = (t: PartnerTab, focus = false) => {
    const params = new URLSearchParams(window.location.search);
    if (t === "overview") params.delete("tab");
    else params.set("tab", t);
    const qs = params.toString();
    // Native history API — Next keeps useSearchParams in sync with it, and a
    // tab switch needs no server round trip (every tab's data is already here).
    window.history.pushState(null, "", `${window.location.pathname}${qs ? `?${qs}` : ""}`);
    if (focus) tabRefs.current[t]?.focus();
  };

  useEffect(() => {
    tabRefs.current[tab]?.scrollIntoView({ block: "nearest", inline: "nearest" });
  }, [tab]);

  const onKey = (e: React.KeyboardEvent) => {
    const i = PARTNER_TABS.indexOf(tab);
    let next: number | null = null;
    if (e.key === "ArrowRight") next = (i + 1) % PARTNER_TABS.length;
    else if (e.key === "ArrowLeft") next = (i - 1 + PARTNER_TABS.length) % PARTNER_TABS.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = PARTNER_TABS.length - 1;
    if (next === null) return;
    e.preventDefault();
    select(PARTNER_TABS[next], true);
  };

  return (
    <>
      <header className="relative flex flex-col gap-4 pb-1 lg:flex-row lg:items-center lg:justify-between">
        <div className="flex min-w-0 max-w-[600px] flex-col gap-3">
          <span className="text-[12.5px] font-extrabold uppercase tracking-[0.24em] text-magenta">Partner Program</span>
          <h1 className="text-[36px] font-extrabold leading-[1.08] tracking-[-0.03em] text-white sm:text-[46px]">
