            <br />
            <span className="bg-gradient-to-r from-[#5fd0ff] via-[#a855f7] to-[#f21cff] bg-clip-text text-transparent">
              Earn.
            </span>
          </h1>
          <p className="max-w-[54ch] text-[13.5px] leading-[1.6] text-tx-mute">
            Every customer attached to your link, and every commission it's earned.
          </p>
        </div>
        <span className="flex flex-none flex-wrap items-center gap-1.5">
          <span className="chip-tone chip-violet">{tier.name} tier</span>
          {typeName && <span className="chip-tone chip-blue">{typeName}</span>}
          <span className={"chip-tone " + (partner.status === "ACTIVE" ? "chip-mint" : "chip-slate")}>
            {partner.status === "ACTIVE" ? "Active" : partner.status}
          </span>
        </span>
      </header>

      <div
        role="tablist"
        aria-label="Partner program sections"
        onKeyDown={onKey}
        className="nx-partner-tabs flex gap-1 overflow-x-auto rounded-[14px] border border-rim-hi bg-[rgba(6,14,36,.72)] p-1.5 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
      >
        {PARTNER_TABS.map((t) => {
          const on = tab === t;
          const meta = PARTNER_TAB_META[t];
          return (
            <button
              key={t}
              ref={(el) => { tabRefs.current[t] = el; }}
              type="button"
              role="tab"
              id={`partner-tab-${t}`}
              aria-selected={on}
              aria-controls={`partner-panel-${t}`}
              tabIndex={on ? 0 : -1}
              onClick={() => select(t)}
              className={
                "flex flex-none items-center gap-2 rounded-[10px] border px-3.5 py-2 text-[13px] font-bold transition outline-none focus-visible:ring-2 focus-visible:ring-[#8b5cff]/70 " +
                (on
                  ? "border-[#8b5cff]/70 bg-[linear-gradient(120deg,rgba(80,40,190,.42),rgba(30,40,120,.3))] text-white"
                  : "border-transparent text-tx-dim hover:bg-white/[0.04] hover:text-white")
              }
            >
              <Icon name={meta.icon} size={14} tone="inherit" className={on ? "text-white" : "text-[#7f9ad0]"} />
              {meta.label}
            </button>
          );
        })}
      </div>

      <div
        role="tabpanel"
        id={`partner-panel-${tab}`}
        aria-labelledby={`partner-tab-${tab}`}
        tabIndex={0}
        className="flex min-w-0 flex-col gap-4 outline-none"
      >
        {tab === "overview" && <OverviewTab partner={partner} onGo={select} />}
        {tab === "analytics" && <PartnerAnalyticsTab data={partner.analytics} />}
        {tab === "customers" && <CustomersTab partner={partner} />}
        {tab === "payouts" && <PayoutsTab partner={partner} onGo={select} />}
