    {
      title: "Your customers get 50% off their first purchase",
      body: <>of any service except domains, and 10% off every purchase after that, forever — shown to them automatically once attached to your link, before they pay.</>,
    },
    {
      title: "Attribution is for life",
      body: <>one partner per customer, permanent, from the moment they sign up through your link. The link carries your code — customers who already had an account before clicking it aren't attached.</>,
    },
    {
      title: "Payouts are arranged by hand",
      body: <>to the payout method you choose in Settings. There's no automatic schedule or minimum configured today — <Link href="/dashboard/support" className="font-semibold text-cyan hover:text-white">contact us</Link> to arrange a payout of your balance.</>,
    },
  ];
  return (
    <div className="grid gap-3 lg:grid-cols-[minmax(0,1fr)_320px]">
      <Panel title="Your terms" sub="How the program works for your account, exactly as the platform applies it.">
        <ul className="flex flex-col gap-3 text-[12.5px] leading-relaxed text-tx-mute">
          {items.map((it) => (
            <li key={it.title} className="flex items-start gap-2.5">
              <Icon name="checkcircle" size={15} tone="mint" className="mt-[1px] flex-none" />
              <span><b className="text-white">{it.title}</b> — {it.body}</span>
            </li>
          ))}
        </ul>
      </Panel>
      <Panel title="Program document">
        {partner.termsPdf ? (
          <>
            <p className="text-[12.5px] leading-relaxed text-tx-mute">The Creator Partner Program terms as a PDF, for your records.</p>
            <a href="/api/creator-partner/terms" className="btn-primary mt-2 h-[40px] gap-2 self-start px-4 text-[13px]">
              <Icon name="download" size={14} tone="inherit" /> Download terms (PDF)
            </a>
            <span className="text-[11px] text-tx-faint" suppressHydrationWarning>
              {Math.max(1, Math.round(partner.termsPdf.sizeBytes / 1024))} KB · updated {fmtDay(partner.termsPdf.updatedAt)}
            </span>
          </>
        ) : (
          <p className="text-[12.5px] leading-relaxed text-tx-mute">
            Questions about any of these terms?{" "}
            <Link href="/dashboard/support" className="font-semibold text-cyan hover:text-white">Contact us</Link> — a real
            person answers.
          </p>
        )}
      </Panel>
    </div>
  );
}

function fmtDay(iso: string): string {
  return new Date(iso).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
}
