"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Icon } from "./Icon";
import { Panel, StatCard } from "./PageShell";
import { useMoney } from "./useMoney";
import { BarChart } from "@/components/ui/bar-chart";
import type { PartnerAnalytics } from "@/lib/partner-analytics";

/* The Partner Program's Analytics tab. Everything is computed server-side
 * (lib/partner-analytics.ts) for the range in the URL; this component only
 * renders it and changes the range. A range change is a real navigation
 * (router.push of ?tab=analytics&range=…), so the server recomputes — no
 * client-side re-aggregation, and the view is linkable. */

const RANGES: { key: string; label: string }[] = [
  { key: "7d", label: "7 days" },
  { key: "30d", label: "30 days" },
  { key: "90d", label: "90 days" },
  { key: "12m", label: "12 months" },
  { key: "all", label: "All time" },
];

const INPUT =
  "h-[36px] rounded-[10px] border border-rim-hi bg-[rgba(4,11,30,.8)] px-3 text-[12.5px] " +
  "text-white outline-none transition focus:border-brand-400/70 [color-scheme:dark]";

function pct(n: number, d: number): string {
  if (d <= 0) return "—";
  return `${Math.round((n / d) * 1000) / 10}%`;
}

function fmtRangeDay(ymd: string): string {
  return new Date(`${ymd}T00:00:00Z`).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" });
}

export function PartnerAnalyticsTab({ data }: { data: PartnerAnalytics }) {
  const money = useMoney();
  const router = useRouter();
  const [pending, start] = useTransition();
  const [customOpen, setCustomOpen] = useState(data.range.key === "custom");
  const [from, setFrom] = useState(data.range.fromDay);
  const [to, setTo] = useState(data.range.toDay);
  const t = data.totals;
  const bucketWord = data.range.bucket === "day" ? "day" : data.range.bucket === "week" ? "week" : "month";

  const go = (params: Record<string, string>) => {
    const qs = new URLSearchParams({ tab: "analytics", ...params });
    start(() => router.push(`/dashboard/partner?${qs}`, { scroll: false }));
  };

  const rangeText = `${fmtRangeDay(data.range.fromDay)} – ${fmtRangeDay(data.range.toDay)}`;
  const hasTraffic = t.clicks + t.signups + t.conversions > 0;
  const hasMoney = data.series.some((p) => p.commissionCents > 0);

  return (
    <div className={"flex flex-col gap-4 transition-opacity " + (pending ? "opacity-60" : "")} aria-busy={pending}>
      {/* Range selector — one row above the charts. */}
      <section className="card flex flex-col gap-3 p-3.5">
        <div className="flex flex-wrap items-center justify-between gap-2.5">
          <div role="group" aria-label="Date range" className="flex flex-wrap gap-1">
            {RANGES.map((r) => {
              const on = data.range.key === r.key && !customOpen;
              return (
                <button
                  key={r.key}
                  type="button"
                  aria-pressed={on}
                  onClick={() => { setCustomOpen(false); go({ range: r.key }); }}
                  className={
                    "h-[34px] rounded-[9px] border px-3 text-[12.5px] font-bold transition " +
                    (on ? "border-[#8b5cff]/70 bg-[rgba(80,40,190,.35)] text-white" : "border-rim-soft text-tx-dim hover:border-rim-hi hover:text-white")
                  }
                >
                  {r.label}
                </button>
              );
            })}
            <button
              type="button"
              aria-pressed={customOpen}
              aria-expanded={customOpen}
              onClick={() => setCustomOpen((v) => !v)}
              className={
                "flex h-[34px] items-center gap-1.5 rounded-[9px] border px-3 text-[12.5px] font-bold transition " +
                (customOpen ? "border-[#8b5cff]/70 bg-[rgba(80,40,190,.35)] text-white" : "border-rim-soft text-tx-dim hover:border-rim-hi hover:text-white")
              }
            >
              <Icon name="calendar" size={13} tone="inherit" /> Custom
            </button>
          </div>
          <span className="text-[12px] text-tx-faint">
            {rangeText} · UTC · per {bucketWord}
            {pending && " · updating…"}
          </span>
        </div>
        {customOpen && (
          <form
            className="flex flex-wrap items-end gap-2.5 border-t border-rim-soft pt-3"
            onSubmit={(e) => { e.preventDefault(); go({ range: "custom", from, to }); }}
          >
            <label className="flex flex-col gap-1">
              <span className="text-[10.5px] font-bold uppercase tracking-[0.1em] text-tx-faint">From</span>
              <input type="date" required value={from} max={to} onChange={(e) => setFrom(e.target.value)} className={INPUT} />
            </label>
            <label className="flex flex-col gap-1">
              <span className="text-[10.5px] font-bold uppercase tracking-[0.1em] text-tx-faint">To</span>
              <input type="date" required value={to} min={from} onChange={(e) => setTo(e.target.value)} className={INPUT} />
            </label>
            <button type="submit" className="btn-primary h-[36px] px-4 text-[12.5px]">Apply</button>
          </form>
        )}
        {data.range.error && (
          <p className="rounded-[9px] border border-amber-500/35 bg-amber-500/10 px-3 py-2 text-[12px] text-amber-300">
            {data.range.error} Showing the last 30 days instead.
          </p>
        )}
      </section>

      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard bareIcon icon="link" value={t.clicks.toLocaleString("en-US")} label="link clicks"
          foot={<span className="text-[11px] text-tx-faint">{pct(t.clicksLedToSignup, t.clicks)} led to a signup</span>} />
        <StatCard bareIcon icon="userplus" tone="violet" value={t.signups.toLocaleString("en-US")} label="signups"
          foot={<span className="text-[11px] text-tx-faint">{t.signups > 0 ? `${t.signupsInRangeWhoPaid} of them have paid · ${pct(t.signupsInRangeWhoPaid, t.signups)}` : "customers attached to you"}</span>} />
        <StatCard bareIcon icon="checkcircle" tone="mint" value={t.conversions.toLocaleString("en-US")} label="paying conversions"
          foot={<span className="text-[11px] text-tx-faint">first paid purchase in this range</span>} />
        <StatCard bareIcon icon="layers" tone="amber" value={money(t.commissionCents)} label="commission earned"
          foot={<span className="text-[11px] text-tx-faint">{t.charges} qualifying {t.charges === 1 ? "charge" : "charges"}</span>} />
      </div>

      <div className="grid gap-3 lg:grid-cols-3">
        <MiniMoney label="Pending payout" hint="earned in this range, not yet settled" value={money(t.accruedCents)} tone="amber" />
        <MiniMoney label="Settled" hint="earned in this range, marked paid" value={money(t.paidRowCents)} tone="mint" />
        <MiniMoney label="Paid to you in this range" hint="real payouts sent (any period's commission)" value={money(t.payoutsCents)} tone="blue" />
      </div>

      <Panel title="Traffic & conversions" sub={`Clicks, signups and first paid purchases per ${bucketWord}. Each chart has its own scale.`}>
        {!hasTraffic ? (
          <Empty icon="linechart">
            No clicks, signups or conversions in this range. When people use your link, each click, each account created
            through it and each first paid purchase is counted here by {bucketWord}.
          </Empty>
        ) : (
          <div className="grid gap-4 xl:grid-cols-3">
            <ChartBlock title="Link clicks" total={t.clicks}>
              <BarChart ariaLabel={`Link clicks per ${bucketWord}, ${rangeText}`} unit=" clicks" color="var(--color-cyan)"
                data={data.series.map((p) => ({ label: p.label, value: p.clicks, title: tipTitle(p.t, data.range.bucket) }))} />
            </ChartBlock>
            <ChartBlock title="Signups" total={t.signups}>
              <BarChart ariaLabel={`Signups per ${bucketWord}, ${rangeText}`} unit=" signups" color="var(--color-violet)"
                data={data.series.map((p) => ({ label: p.label, value: p.signups, title: tipTitle(p.t, data.range.bucket) }))} />
            </ChartBlock>
            <ChartBlock title="Paying conversions" total={t.conversions}>
              <BarChart ariaLabel={`Paying conversions per ${bucketWord}, ${rangeText}`} unit=" conversions" color="var(--color-mint)"
                data={data.series.map((p) => ({ label: p.label, value: p.conversions, title: tipTitle(p.t, data.range.bucket) }))} />
            </ChartBlock>
          </div>
        )}
      </Panel>

      <Panel title="Commission over time" sub={`Commission earned per ${bucketWord} (pending + settled; voided entries excluded).`}>
        {!hasMoney ? (
          <Empty icon="barchart">
            No commission earned in this range. Every time a customer attached to you is charged for a service, the
            commission lands here on the day it accrued.
          </Empty>
        ) : (
          <>
            <BarChart ariaLabel={`Commission per ${bucketWord}, ${rangeText}`} height={220} integer={false} color="var(--color-magenta)"
              format={(v) => money(Math.round(v))}
              data={data.series.map((p) => ({ label: p.label, value: p.commissionCents, title: tipTitle(p.t, data.range.bucket) }))} />
            <details className="mt-1 text-[12px] text-tx-faint">
              <summary className="cursor-pointer select-none font-semibold text-tx-dim">View as table</summary>
              <div className="mt-2 max-h-[260px] overflow-auto">
                <table className="w-full text-[12px]">
                  <thead>
                    <tr className="border-b border-rim-soft text-left text-[10.5px] uppercase tracking-[0.06em]">
                      <th className="py-1.5 pr-3 font-semibold">{bucketWord === "day" ? "Day" : bucketWord === "week" ? "Week of" : "Month"}</th>
                      <th className="py-1.5 pr-3 text-right font-semibold">Clicks</th>
                      <th className="py-1.5 pr-3 text-right font-semibold">Signups</th>
                      <th className="py-1.5 pr-3 text-right font-semibold">Conversions</th>
                      <th className="py-1.5 text-right font-semibold">Commission</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data.series.map((p) => (
                      <tr key={p.t} className="border-b border-rim-soft last:border-0">
                        <td className="py-1.5 pr-3">{tipTitle(p.t, data.range.bucket)}</td>
                        <td className="mono py-1.5 pr-3 text-right">{p.clicks}</td>
                        <td className="mono py-1.5 pr-3 text-right">{p.signups}</td>
                        <td className="mono py-1.5 pr-3 text-right">{p.conversions}</td>
                        <td className="mono py-1.5 text-right text-tx-dim">{money(p.commissionCents)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </details>
          </>
        )}
      </Panel>

      <div className="grid gap-3 lg:grid-cols-[360px_minmax(0,1fr)]">
        <Panel title="Top sources" sub="Where your link clicks came from — the referring site the browser reported.">
          {data.sources.length === 0 ? (
            <Empty icon="globe">No clicks in this range yet — the sites sending you traffic will be ranked here.</Empty>
          ) : (
            <ul className="flex flex-col gap-2">
              {data.sources.map((s) => (
                <li key={s.source} className="flex flex-col gap-1">
                  <span className="flex items-baseline justify-between gap-2 text-[12.5px]">
                    <span className="truncate text-tx-dim">{s.source}</span>
                    <span className="mono flex-none text-tx-faint">
                      {s.clicks} {s.clicks === 1 ? "click" : "clicks"}{s.signups > 0 ? ` · ${s.signups} signup${s.signups === 1 ? "" : "s"}` : ""}
                    </span>
                  </span>
                  <span className="h-[6px] w-full rounded-full bg-[var(--color-rim-soft)]">
                    <span className="block h-[6px] rounded-full bg-[var(--color-cyan)]" style={{ width: `${Math.max(3, (s.clicks / data.sources[0].clicks) * 100)}%` }} />
                  </span>
                </li>
              ))}
              <li className="pt-1 text-[11px] leading-relaxed text-tx-faint">
                Many apps (Discord, Instagram, email clients) don&apos;t share where a click came from — those count as
                &ldquo;Direct / not shared&rdquo;.
              </li>
            </ul>
          )}
        </Panel>

        <Panel title="Commission events" sub={`Each qualifying charge in this range${data.eventsTruncated ? " — the most recent 300 shown" : ""}.`} bodyClass="gap-0">
          {data.events.length === 0 ? (
            <Empty icon="file">No commission entries in this range. Each charge on one of your customers&apos; accounts is listed here with its date, product and status.</Empty>
          ) : (
            <div className="max-h-[520px] overflow-auto">
              <table className="w-full min-w-[620px] text-[12.5px]">
                <thead className="sticky top-0 bg-[var(--color-well)]">
                  <tr className="border-b border-rim-soft text-left text-[11px] uppercase tracking-[0.06em] text-tx-faint">
                    <th className="py-2 pr-3 font-semibold">Date</th>
                    <th className="py-2 pr-3 font-semibold">Customer</th>
                    <th className="py-2 pr-3 font-semibold">Product</th>
                    <th className="py-2 pr-3 text-right font-semibold">Charge (net)</th>
                    <th className="py-2 pr-3 text-right font-semibold">Commission</th>
                    <th className="py-2 pl-3 font-semibold">Status</th>
                  </tr>
                </thead>
                <tbody>
                  {data.events.map((e) => (
                    <tr key={e.id} className="border-b border-rim-soft last:border-0">
                      <td className="whitespace-nowrap py-2.5 pr-3 text-[11.5px] text-tx-faint" suppressHydrationWarning>
                        {new Date(e.when).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}
                      </td>
                      <td className="max-w-[180px] truncate py-2.5 pr-3 text-tx-dim">{e.customer}</td>
                      <td className="py-2.5 pr-3 text-tx-dim">
                        {e.product}
                        <span className="ml-1.5 text-[11px] text-tx-faint">{e.kind === "RENEWAL" ? "renewal" : e.kind === "ORDER" ? "order" : ""}</span>
                      </td>
                      <td className="mono py-2.5 pr-3 text-right text-tx-faint">{money(e.baseCents)}</td>
                      <td className="mono py-2.5 pr-3 text-right text-tx-dim">{money(e.amountCents)}</td>
                      <td className="py-2.5 pl-3">
                        <span className={"chip-tone " + (e.status === "PAID" ? "chip-mint" : e.status === "VOID" ? "chip-slate" : "chip-amber")}>
                          {e.status === "ACCRUED" ? "pending" : e.status.toLowerCase()}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </Panel>
      </div>
    </div>
  );
}

function tipTitle(iso: string, bucket: string): string {
  const d = new Date(iso);
  if (bucket === "month") return d.toLocaleDateString("en-US", { month: "long", year: "numeric", timeZone: "UTC" });
  const day = d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" });
  return bucket === "week" ? `Week of ${day}` : day;
}

function ChartBlock({ title, total, children }: { title: string; total: number; children: React.ReactNode }) {
  return (
    <div className="flex min-w-0 flex-col gap-1.5">
      <span className="flex items-baseline justify-between gap-2">
        <span className="text-[12.5px] font-bold text-white">{title}</span>
        <span className="mono text-[12px] text-tx-faint">{total.toLocaleString("en-US")} total</span>
      </span>
      {children}
    </div>
  );
}

function MiniMoney({ label, hint, value, tone }: { label: string; hint: string; value: string; tone: "amber" | "mint" | "blue" }) {
  const dot = tone === "amber" ? "bg-amber-400" : tone === "mint" ? "bg-emerald-400" : "bg-[#2f7eef]";
  return (
    <section className="card flex items-center justify-between gap-3 p-3.5">
      <span className="flex min-w-0 flex-col gap-0.5">
        <span className="flex items-center gap-1.5 text-[12px] font-bold text-tx-dim">
          <span className={"h-2 w-2 flex-none rounded-full " + dot} aria-hidden /> {label}
        </span>
        <span className="text-[11px] text-tx-faint">{hint}</span>
      </span>
      <span className="num flex-none text-[19px] text-white">{value}</span>
    </section>
  );
}

function Empty({ icon, children }: { icon: string; children: React.ReactNode }) {
  return (
    <div className="flex items-start gap-3 rounded-[11px] border border-dashed border-rim-hi px-4 py-5">
      <Icon name={icon} size={18} className="mt-[1px] flex-none opacity-70" />
      <p className="text-[12.5px] leading-relaxed text-tx-faint">{children}</p>
    </div>
  );
}

