"use client";

import { useActionState, useState } from "react";
import { Icon } from "./Icon";
import { Panel } from "./PageShell";
import { savePartnerContact, savePartnerPayoutMethod, type PartnerSettingsState } from "@/lib/actions-partner-profile";
import { PAYOUT_METHODS, CRYPTO_NETWORKS, type PayoutMethodKey } from "@/lib/partner-payout";
import type { PartnerPayoutView } from "@/lib/partner-payout-store";

/* The Partner Program's Settings tab: the partner's own contact details and
 * their PREFERRED payout method. Payouts stay manual — the Nxeon team pays by
 * hand; this tells them where. Saved payout details are never sent back to
 * the browser: the partner sees a masked summary, and changing the method
 * means entering the details again (see lib/partner-payout-store.ts). */

const INPUT =
  "h-[42px] w-full rounded-[10px] border border-rim-hi bg-[rgba(4,11,30,.8)] px-3.5 text-[13.5px] " +
  "text-white outline-none transition placeholder:text-tx-faint focus:border-brand-400/70";

function Field({ label, hint, error, children }: { label: string; hint?: string; error?: string; children: React.ReactNode }) {
  return (
    <label className="flex min-w-0 flex-col gap-1.5">
      <span className="text-[11px] font-bold uppercase tracking-[0.1em] text-tx-faint">{label}</span>
      {children}
      {error ? <span className="text-[11.5px] text-red-300">{error}</span> : hint ? <span className="text-[11px] text-tx-faint">{hint}</span> : null}
    </label>
  );
}

function Result({ state, okText = "Saved" }: { state: PartnerSettingsState; okText?: string }) {
  if (state.error) {
    return <p role="alert" className="rounded-[9px] border border-red-500/35 bg-red-500/10 px-3 py-2 text-[12.5px] text-red-300">{state.error}</p>;
  }
  if (state.ok) return <p role="status" className="text-[12.5px] font-semibold text-emerald-400">{okText} ✓</p>;
  return null;
}

export function PartnerSettingsTab({ payout }: { payout: PartnerPayoutView }) {
  const [cState, cAction, cPending] = useActionState(savePartnerContact, {} as PartnerSettingsState);
  const [pState, pAction, pPending] = useActionState(savePartnerPayoutMethod, {} as PartnerSettingsState);
  const [method, setMethod] = useState<PayoutMethodKey | "">("");
  const [editing, setEditing] = useState(!payout.summary);
  const c = payout.contact;
  const fe = cState.fieldErrors ?? {};
  const pe = pState.fieldErrors ?? {};

  return (
    <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
      <Panel title="Contact details" sub="How the Nxeon team reaches you about your partnership and payouts.">
        <form action={cAction} className="flex flex-col gap-4">
          <div className="grid gap-4 sm:grid-cols-2">
            <Field label="Contact name" error={fe.contactName}>
              <input name="contactName" defaultValue={c.contactName} maxLength={120} autoComplete="name" className={INPUT} />
            </Field>
            <Field label="Contact email" error={fe.contactEmail} hint="Can differ from your login email.">
              <input name="contactEmail" type="email" defaultValue={c.contactEmail} maxLength={200} autoComplete="email" className={INPUT} />
            </Field>
            <Field label="Phone / WhatsApp (optional)" error={fe.phone}>
              <input name="phone" type="tel" defaultValue={c.phone} maxLength={40} autoComplete="tel" placeholder="+1 555 010 0000" className={INPUT} />
            </Field>
            <Field label="Discord (optional)" error={fe.discord}>
              <input name="discord" defaultValue={c.discord} maxLength={64} placeholder="username" className={INPUT} />
            </Field>
          </div>
          <Field label="Main channel or social handle (optional)" error={fe.social} hint="e.g. youtube.com/@yourchannel or @handle">
            <input name="social" defaultValue={c.social} maxLength={200} className={INPUT} />
          </Field>
          <div className="flex flex-wrap items-center gap-3">
            <button type="submit" disabled={cPending} className="nx-cta px-5 py-2.5 text-[13px] disabled:opacity-60">
              {cPending ? "Saving…" : "Save contact details"}
            </button>
            <Result state={cState} />
          </div>
        </form>
      </Panel>

      <Panel title="Preferred payout method" sub="Payouts are sent by hand by the Nxeon team — this is where we'll send yours.">
        {payout.summary && (
          <div className="flex flex-wrap items-center justify-between gap-3 rounded-[11px] border border-rim-soft bg-well px-3.5 py-3">
            <span className="flex min-w-0 items-center gap-2.5">
              <Icon name="lock" size={15} tone="mint" className="flex-none" />
              <span className="flex min-w-0 flex-col">
                <span className="truncate text-[13px] font-semibold text-white">{payout.summary}</span>
                <span className="text-[11px] text-tx-faint" suppressHydrationWarning>
                  Stored encrypted{payout.hasNote ? " · with a note" : ""}
                  {payout.updatedAt ? ` · updated ${new Date(payout.updatedAt).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}` : ""}
                </span>
              </span>
            </span>
            {!editing && (
              <button type="button" onClick={() => setEditing(true)} className="btn-secondary h-[34px] px-3.5 text-[12.5px]">
                Change
              </button>
            )}
          </div>
        )}

        {editing && (
          <form action={pAction} className="mt-1 flex flex-col gap-4">
            <fieldset className="flex flex-col gap-2">
              <legend className="mb-1.5 text-[11px] font-bold uppercase tracking-[0.1em] text-tx-faint">Method</legend>
              <div className="grid gap-2 sm:grid-cols-2">
                {PAYOUT_METHODS.map((m) => {
                  const on = method === m.key;
                  return (
                    <label
                      key={m.key}
                      className={
                        "flex cursor-pointer items-start gap-2.5 rounded-[11px] border px-3 py-2.5 transition " +
                        (on ? "border-[#8b5cff]/70 bg-[rgba(80,40,190,.22)]" : "border-rim-soft hover:border-rim-hi")
                      }
                    >
                      <input
                        type="radio"
                        name="method"
                        value={m.key}
                        checked={on}
                        onChange={() => setMethod(m.key)}
                        className="mt-[3px] accent-[#8b5cff]"
                      />
                      <span className="flex min-w-0 flex-col">
                        <span className="text-[13px] font-bold text-white">{m.label}</span>
                        <span className="text-[11px] leading-snug text-tx-faint">{m.blurb}</span>
                      </span>
                    </label>
                  );
                })}
              </div>
            </fieldset>

            {method === "PAYPAL" && (
              <Field label="PayPal email" error={pe.paypalEmail}>
                <input name="paypalEmail" type="email" required maxLength={200} autoComplete="off" className={INPUT} />
              </Field>
            )}
            {method === "WISE" && (
              <div className="grid gap-4 sm:grid-cols-2">
                <Field label="Wise account email" error={pe.wiseEmail}>
                  <input name="wiseEmail" type="email" required maxLength={200} autoComplete="off" className={INPUT} />
                </Field>
                <Field label="Account holder (optional)" error={pe.accountHolder}>
                  <input name="accountHolder" maxLength={120} autoComplete="off" className={INPUT} />
                </Field>
              </div>
            )}
            {method === "BANK" && (
              <div className="flex flex-col gap-4">
                <div className="grid gap-4 sm:grid-cols-2">
                  <Field label="Account holder name" error={pe.accountName}>
                    <input name="accountName" required maxLength={120} autoComplete="off" className={INPUT} />
                  </Field>
                  <Field label="Bank name (optional)" error={pe.bankName}>
                    <input name="bankName" maxLength={120} autoComplete="off" className={INPUT} />
                  </Field>
                  <Field label="Bank country (optional)" error={pe.country}>
                    <input name="country" maxLength={80} autoComplete="off" className={INPUT} />
                  </Field>
                </div>
                <p className="text-[11.5px] leading-relaxed text-tx-faint">
                  Enter an <b className="text-tx-dim">IBAN + SWIFT/BIC</b> (Europe and most international transfers) <i>or</i> an{" "}
                  <b className="text-tx-dim">account number + routing / sort code</b>.
                </p>
                <div className="grid gap-4 sm:grid-cols-2">
                  <Field label="IBAN" error={pe.iban}>
                    <input name="iban" maxLength={42} autoComplete="off" spellCheck={false} className={INPUT + " mono uppercase"} />
                  </Field>
                  <Field label="SWIFT / BIC" error={pe.swift}>
                    <input name="swift" maxLength={11} autoComplete="off" spellCheck={false} className={INPUT + " mono uppercase"} />
                  </Field>
                  <Field label="Account number" error={pe.accountNumber}>
                    <input name="accountNumber" maxLength={34} autoComplete="off" spellCheck={false} className={INPUT + " mono"} />
                  </Field>
                  <Field label="Routing / sort code" error={pe.routingNumber}>
                    <input name="routingNumber" maxLength={20} autoComplete="off" spellCheck={false} className={INPUT + " mono"} />
                  </Field>
                </div>
              </div>
            )}
            {method === "CRYPTO" && (
              <div className="flex flex-col gap-4">
                <div className="grid gap-4 sm:grid-cols-2">
                  <Field label="Coin" error={pe.asset} hint="e.g. USDT, USDC, BTC">
                    <input name="asset" required maxLength={16} autoComplete="off" className={INPUT + " uppercase"} />
                  </Field>
                  <Field label="Network" error={pe.network}>
                    <span className="relative flex items-center">
                      <select name="network" required defaultValue="" className={INPUT + " cursor-pointer appearance-none pr-9"}>
                        <option value="" disabled>Choose a network</option>
                        {CRYPTO_NETWORKS.map((n) => <option key={n} value={n}>{n}</option>)}
                      </select>
                      <svg aria-hidden width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"
                           strokeLinecap="round" strokeLinejoin="round" className="pointer-events-none absolute right-3.5 text-tx-faint">
                        <path d="m6 9 6 6 6-6" />
                      </svg>
                    </span>
                  </Field>
                </div>
                <Field label="Wallet address" error={pe.walletAddress} hint="Double-check it — a payment sent to the wrong address or network can't be recovered.">
                  <input name="walletAddress" required maxLength={120} autoComplete="off" spellCheck={false} className={INPUT + " mono"} />
                </Field>
              </div>
            )}

            {method && (
              <Field label="Note for the payouts team (optional)" error={pe.note}>
                <textarea
                  name="note"
                  maxLength={500}
                  rows={3}
                  placeholder="Anything we should know — preferred currency, reference to include…"
                  className={INPUT + " h-auto py-2.5 leading-relaxed"}
                />
              </Field>
            )}

            <p className="flex items-start gap-2 text-[11.5px] leading-relaxed text-tx-faint">
              <Icon name="shieldcheck" size={14} tone="mint" className="mt-[1px] flex-none" />
              Payout details are encrypted before they're stored and only shown to the Nxeon team who sends payouts. We
              email your account address whenever they change.
            </p>

            <div className="flex flex-wrap items-center gap-3">
              <button type="submit" disabled={pPending || !method} className="nx-cta px-5 py-2.5 text-[13px] disabled:opacity-60">
                {pPending ? "Saving…" : "Save payout method"}
              </button>
              {payout.summary && (
                <button type="button" onClick={() => { setEditing(false); setMethod(""); }} className="btn-secondary h-[40px] px-4 text-[12.5px]">
                  Cancel
                </button>
              )}
              <Result state={pState} okText="Payout method saved" />
            </div>
          </form>
        )}
        {!editing && pState.ok && <Result state={pState} okText="Payout method saved" />}
      </Panel>
    </div>
  );
}

