3	// Admin server actions for the KOL / Agency partner program: create & manage
4	// partners and their commission rates, attach/detach customers, and settle
5	// accrued commission (mark PAID). Billing-area gated, mirroring the existing
6	// affiliate admin actions in lib/actions-affiliate.ts.
7	//
8	// Also holds the Creator Partner Program's PARTNER LOGIN INVITE flow
9	// (adminCreatePartnerInvite / acceptPartnerInvite / adminRevokePartnerInvite,
10	// 2026-09-26) and partial-payout recording (adminRecordPartnerPayout) — the two
11	// admin-facing gaps the owner's spec called out: today `adminCreatePartner`
12	// only LINKS an existing account by email, and `adminSettlePartnerCommission`
13	// only supports settling the FULL accrued balance at once.
14	
15	import { revalidatePath } from "next/cache";
16	import { redirect } from "next/navigation";
17	import { randomBytes, createHash } from "node:crypto";
18	import bcrypt from "bcryptjs";
19	import { db } from "./db";
20	import { requireArea } from "./rbac";
21	import { createSession } from "./auth";
22	
23	/** Normalise a partner code: uppercase, alphanumerics/dash, trimmed. */
24	function normalizeCode(raw: string): string {
25	  return raw
26	    .trim()
27	    .toUpperCase()
28	    .replace(/[^A-Z0-9-]/g, "")
29	    .slice(0, 32);
30	}
31	
32	/** Clamp a percent to a sane 0–90 range (integer-ish, 2dp). */
33	function clampRate(raw: number): number {
34	  if (!Number.isFinite(raw)) return 0;
35	  return Math.min(90, Math.max(0, Math.round(raw * 100) / 100));
36	}
37	
38	// ---------- Create a partner ----------
39	
40	export async function adminCreatePartner(
41	  _prev: unknown,
42	  formData: FormData
43	): Promise<{ error?: string; ok?: boolean }> {
44	  const admin = await requireArea("billing");
45	
46	  const name = String(formData.get("name") ?? "").trim();
47	  const code = normalizeCode(String(formData.get("code") ?? ""));
48	  const contactEmail = String(formData.get("contactEmail") ?? "").trim() || null;
49	  const rate = clampRate(Number(formData.get("commissionRatePct")));
50	
51	  if (!name) return { error: "Partner name is required." };
52	  if (code.length < 3) return { error: "Code must be at least 3 characters (A–Z, 0–9, dash)." };
53	  if (rate <= 0) return { error: "Commission rate must be greater than 0%." };
54	
55	  const clash = await db.referralPartner.findUnique({ where: { code } });
56	  if (clash) return { error: "That code is already in use." };
57	
58	  // Optional: link the partner to an existing user account (by email) so they can
59	  // sign in and see their portal. Silently skipped if no such user.
60	  const linkEmail = String(formData.get("linkEmail") ?? "").trim().toLowerCase();
61	  let userId: string | null = null;
62	  if (linkEmail) {
63	    const u = await db.user.findUnique({ where: { email: linkEmail }, select: { id: true } });
64	    if (!u) return { error: `No user account found for ${linkEmail}.` };
65	    const taken = await db.referralPartner.findUnique({ where: { userId: u.id } });
66	    if (taken) return { error: "That user is already a partner." };
67	    userId = u.id;
68	  }
69	
70	  const partner = await db.referralPartner.create({
71	    data: { name, code, contactEmail, commissionRatePct: rate, userId, status: "ACTIVE" },
72	  });
73	  await db.auditLog.create({
74	    data: {
75	      userId: admin.id,
76	      action: "partner.create",
77	      detail: `${partner.name} (${partner.code}) @ ${rate}%`,
78	    },
79	  });
80	  revalidatePath("/admin/partners");
81	  return { ok: true };
82	}
83	
84	// ---------- Update rate / status ----------
85	
86	export async function adminUpdatePartner(
87	  id: string,
88	  patch: { commissionRatePct?: number; status?: string }
89	): Promise<{ error?: string; ok?: boolean }> {
90	  const admin = await requireArea("billing");
91	  const partner = await db.referralPartner.findUnique({ where: { id } });
92	  if (!partner) return { error: "Partner not found." };
93	
94	  const data: { commissionRatePct?: number; status?: string } = {};
95	  if (patch.commissionRatePct != null) {
96	    const rate = clampRate(patch.commissionRatePct);
97	    if (rate <= 0) return { error: "Commission rate must be greater than 0%." };
98	    data.commissionRatePct = rate;
99	  }
100	  if (patch.status != null) {
101	    if (patch.status !== "ACTIVE" && patch.status !== "PAUSED") {
102	      return { error: "Invalid status." };
103	    }
104	    data.status = patch.status;
105	  }
106	  if (Object.keys(data).length === 0) return { error: "Nothing to update." };
107	
108	  await db.referralPartner.update({ where: { id }, data });
109	  await db.auditLog.create({
110	    data: {
111	      userId: admin.id,
112	      action: "partner.update",
113	      detail: `${partner.code} ${JSON.stringify(data)}`,
114	    },
115	  });
116	  revalidatePath("/admin/partners");
117	  revalidatePath(`/admin/partners/${id}`);
118	  return { ok: true };
119	}
120	
121	// ---------- Attach / detach a customer ----------
122	
123	/**
124	 * Attach a customer (by email) to a partner for life. Enforces the single-partner
125	 * rule (a customer already attached to a partner cannot be moved — the unique
126	 * `customerId` also hard-stops it) so attribution is never silently reassigned.
127	 */
128	export async function adminAttachCustomer(
129	  partnerId: string,
130	  email: string
131	): Promise<{ error?: string; ok?: boolean }> {
132	  const admin = await requireArea("billing");
133	  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
134	  if (!partner) return { error: "Partner not found." };
135	
136	  const customer = await db.user.findUnique({
137	    where: { email: email.trim().toLowerCase() },
138	    select: { id: true },
139	  });
140	  if (!customer) return { error: "No customer found with that email." };
141	  if (partner.userId && partner.userId === customer.id) {
142	    return { error: "A partner cannot be attached to their own account." };
143	  }
144	
145	  const existing = await db.partnerCustomer.findUnique({
146	    where: { customerId: customer.id },
147	    include: { partner: { select: { name: true } } },
148	  });
149	  if (existing) {
150	    return existing.partnerId === partnerId
151	      ? { error: "That customer is already attached to this partner." }
152	      : { error: `That customer is already attached to ${existing.partner.name}.` };
153	  }
154	
155	  await db.partnerCustomer.create({ data: { partnerId, customerId: customer.id } });
156	  await db.auditLog.create({
157	    data: { userId: admin.id, action: "partner.attach", detail: `${partner.code} <- ${email}` },
158	  });
159	  revalidatePath(`/admin/partners/${partnerId}`);
160	  return { ok: true };
161	}
162	
163	/**
164	 * Detach a customer from a partner. Historical commission rows are LEFT INTACT
165	 * (they record charges that really happened); only the forward attachment is
166	 * removed, so no new commission accrues for this customer afterwards.
167	 */
168	export async function adminDetachCustomer(
169	  attachmentId: string
170	): Promise<{ error?: string; ok?: boolean }> {
171	  const admin = await requireArea("billing");
172	  const attachment = await db.partnerCustomer.findUnique({ where: { id: attachmentId } });
173	  if (!attachment) return { error: "Attachment not found." };
174	
175	  await db.partnerCustomer.delete({ where: { id: attachmentId } });
176	  await db.auditLog.create({
177	    data: {
178	      userId: admin.id,
179	      action: "partner.detach",
180	      detail: `${attachment.partnerId} -/- ${attachment.customerId}`,
181	    },
182	  });
183	  revalidatePath(`/admin/partners/${attachment.partnerId}`);
184	  return { ok: true };
185	}
186	
187	// ---------- Settle commission (mark accrued -> paid) ----------
188	
189	/**
190	 * Mark all currently-ACCRUED commission for a partner as PAID, stamping `paidAt`,
191	 * AND record one `PartnerPayout` for the partner's real outstanding balance (see
192	 * PartnerPayout's own doc comment for why the real balance is
193	 * lifetime-earned-minus-payouts, not a sum of ACCRUED rows — a prior PARTIAL
194	 * payout via `adminRecordPartnerPayout` already reduced it). This records a
195	 * settlement OUTSIDE the wallet (partners are typically paid by bank transfer /
196	 * invoice), so unlike the affiliate cash-out it moves no wallet balance.
197	 */
198	export async function adminSettlePartnerCommission(
199	  partnerId: string
200	): Promise<{ error?: string; ok?: boolean; count?: number; cents?: number }> {
201	  const admin = await requireArea("billing");
202	  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
203	  if (!partner) return { error: "Partner not found." };
204	
205	  const { computePartnerSummary } = await import("./partner-commission");
206	  const summary = await computePartnerSummary(partnerId);
207	  const cents = summary?.outstandingCents ?? 0;
208	  const agg = await db.partnerCommission.aggregate({
209	    where: { partnerId, status: "ACCRUED" },
210	    _count: true,
211	  });
212	  const count = agg._count ?? 0;
213	  if (cents <= 0) return { error: "Nothing to settle — no outstanding balance." };
214	
215	  await db.$transaction([
216	    db.partnerCommission.updateMany({
217	      where: { partnerId, status: "ACCRUED" },
218	      data: { status: "PAID", paidAt: new Date() },
219	    }),
220	    db.partnerPayout.create({
221	      data: { partnerId, amountCents: cents, note: "Full settlement", createdById: admin.id },
222	    }),
223	  ]);
224	  await db.auditLog.create({
225	    data: {
226	      userId: admin.id,
227	      action: "partner.settle",
228	      detail: `${partner.code}: ${count} rows, $${(cents / 100).toFixed(2)}`,
229	    },
230	  });
231	  revalidatePath(`/admin/partners/${partnerId}`);
232	  revalidatePath("/admin/partners");
233	  return { ok: true, count, cents };
234	}
235	
236	/**
237	 * Record a PARTIAL (or exact) payment made to a partner off-wallet — "I paid
238	 * them $340 today even though $412 is accrued" (the owner's own example). Unlike
239	 * `adminSettlePartnerCommission`, this never touches individual PartnerCommission
240	 * row statuses — see PartnerPayout's own doc comment for why a separate payments
241	 * ledger is the honest way to support a partial amount. Refuses to overpay past
242	 * the real outstanding balance.
243	 */
244	export async function adminRecordPartnerPayout(
245	  partnerId: string,
246	  amountCents: number,
247	  note?: string
248	): Promise<{ error?: string; ok?: boolean }> {
249	  const admin = await requireArea("billing");
250	  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
251	  if (!partner) return { error: "Partner not found." };
252	
253	  const cents = Math.round(Number(amountCents));
254	  if (!Number.isFinite(cents) || cents <= 0) return { error: "Enter a positive amount." };
255	
256	  const { computePartnerSummary } = await import("./partner-commission");
257	  const summary = await computePartnerSummary(partnerId);
258	  const outstanding = summary?.outstandingCents ?? 0;
259	  if (cents > outstanding) {
260	    return { error: `That's more than the outstanding balance ($${(outstanding / 100).toFixed(2)}).` };
261	  }
262	
263	  await db.partnerPayout.create({
264	    data: { partnerId, amountCents: cents, note: note?.trim().slice(0, 300) || null, createdById: admin.id },
265	  });
266	  await db.auditLog.create({
267	    data: {
268	      userId: admin.id,
269	      action: "partner.payout",
270	      detail: `${partner.code}: $${(cents / 100).toFixed(2)}${note ? ` (${note.trim().slice(0, 100)})` : ""}`,
271	    },
272	  });
273	  revalidatePath(`/admin/partners/${partnerId}`);
274	  revalidatePath("/admin/partners");
275	  return { ok: true };
276	}
277	
278	// ---------- Partner login invites (a brand-new account, not a link) ----------
279	
280	const PARTNER_INVITE_TTL_HOURS = 72;
281	
282	/**
283	 * Invite a brand-new (non-customer) login for a partner who doesn't have an
284	 * Nxeon account yet — the gap `adminCreatePartner`'s `linkEmail` field can't
285	 * fill (it only links an EXISTING account). Mirrors `inviteMember`'s token/hash/
286	 * expiry mechanics (lib/actions-teams.ts) with one real difference: the invitee
287	 * has no account to sign in with yet, so `acceptPartnerInvite` below creates one
288	 * — it cannot require `requireUser()` first.
289	 *
290	 * Deliberately DOES check whether the address already has an account (unlike
291	 * `inviteMember`'s enumeration-safe design) — this is an admin-only action
292	 * against an address the admin themself typed, not a customer-facing endpoint
293	 * an attacker could probe, and the check exists to point the admin at the right
294	 * tool (`linkEmail`) instead of silently minting an invite that can never be
295	 * redeemed (acceptPartnerInvite refuses if the address already has an account).
296	 */
297	export async function adminCreatePartnerInvite(
298	  partnerId: string,
299	  email: string
300	): Promise<{ error?: string; ok?: boolean; message?: string }> {
301	  const admin = await requireArea("billing");
302	  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
303	  if (!partner) return { error: "Partner not found." };
304	  if (partner.userId) return { error: "This partner already has a login." };
305	
306	  const invitedEmail = String(email ?? "").trim().toLowerCase();
307	  if (!invitedEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(invitedEmail)) {
308	    return { error: "Enter a valid email address." };
309	  }
310	  const existingUser = await db.user.findUnique({ where: { email: invitedEmail }, select: { id: true } });
311	  if (existingUser) {
312	    return { error: `An account already exists for ${invitedEmail} — use "Link existing user by email" instead.` };
313	  }
314	
315	  const token = randomBytes(32).toString("base64url");
316	  const tokenHash = createHash("sha256").update(token).digest("hex");
317	  const expiresAt = new Date(Date.now() + PARTNER_INVITE_TTL_HOURS * 60 * 60 * 1000);
318	
319	  await db.partnerInvite.create({
320	    data: { partnerId, email: invitedEmail, tokenHash, invitedById: admin.id, expiresAt },
321	  });
322	
323	  const base = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/+$/, "");
324	  const acceptUrl = `${base}/partner/invite/accept?token=${encodeURIComponent(token)}`;
325	
326	  const { sendMail, emails } = await import("./mailer");
327	  const tpl = emails.genericNotification({
328	    heading: `You're invited to become an Nxeon Partner`,
329	    message:
330	      `Nxeon has invited you to set up your Partner login for <b>${partner.name}</b> (code <b>${partner.code}</b>). ` +
331	      `Set a password to access your real-time click/signup/conversion tracking, your commission balance and payout ` +
332	      `history, and your partner link — <code>${base}/partner/${partner.code}</code>. ` +
333	      `This invitation link expires in ${PARTNER_INVITE_TTL_HOURS} hours.`,
334	    ctaLabel: "Set up your Partner account",
335	    ctaUrl: acceptUrl,
336	  });
337	  const sent = await sendMail({ to: invitedEmail, subject: tpl.subject, html: tpl.html, template: tpl.template });
338	  if (!sent) {
339	    return { error: "We couldn't send that invitation email. Check mail settings and try again." };
340	  }
341	
342	  await db.auditLog.create({
343	    data: { userId: admin.id, action: "partner.invite_sent", detail: `${partner.code} -> ${invitedEmail}` },
344	  });
345	  revalidatePath(`/admin/partners/${partnerId}`);
346	  return { ok: true, message: `Invitation emailed to ${invitedEmail}. It expires in ${PARTNER_INVITE_TTL_HOURS} hours.` };
347	}
348	
349	/** Cancel an outstanding partner invite so its link stops working. */
350	export async function adminRevokePartnerInvite(inviteId: string): Promise<{ error?: string; ok?: boolean }> {
351	  const admin = await requireArea("billing");
352	  const invite = await db.partnerInvite.findUnique({ where: { id: inviteId } });
353	  if (!invite) return { error: "Invite not found." };
354	  await db.partnerInvite.update({ where: { id: inviteId }, data: { revokedAt: new Date() } });
355	  await db.auditLog.create({
356	    data: { userId: admin.id, action: "partner.invite_revoked", detail: `${invite.partnerId}: ${invite.email}` },
357	  });
358	  revalidatePath(`/admin/partners/${invite.partnerId}`);
359	  return { ok: true };
360	}
361	
362	/**
363	 * Redeem a partner invite: create the new account (no `requireUser()` — the
364	 * whole point is this person has no session yet), link it to the partner, sign
365	 * them in, and mark the invite accepted. Public (no auth required to CALL this
366	 * action — a signed-in session is what it CREATES), but the token is the only
367	 * thing that authorises anything, exactly like acceptInvite's team-invite
368	 * counterpart.
369	 */
370	export async function acceptPartnerInvite(
371	  _prev: unknown,
372	  formData: FormData
373	): Promise<{ error?: string; ok?: boolean }> {
374	  const token = String(formData.get("token") ?? "");
375	  const name = String(formData.get("name") ?? "").trim();
376	  const password = String(formData.get("password") ?? "");
377	
378	  if (!token) return { error: "Missing invitation token." };
379	  if (!name) return { error: "Enter your name." };
380	  if (password.length < 8 || !/[a-zA-Z]/.test(password) || !/[0-9]/.test(password)) {
381	    return { error: "Password must be at least 8 characters and include a letter and a number." };
382	  }
383	
384	  const tokenHash = createHash("sha256").update(token).digest("hex");
385	  const invite = await db.partnerInvite.findUnique({ where: { tokenHash } });
386	  if (!invite) return { error: "This invitation link is invalid." };
387	  if (invite.revokedAt) return { error: "This invitation has been cancelled. Ask for a new one." };
388	  if (invite.acceptedAt) return { error: "This invitation has already been used. Sign in instead." };
389	  if (invite.expiresAt < new Date()) return { error: "This invitation link has expired. Ask for a new one." };
390	
391	  const partner = await db.referralPartner.findUnique({ where: { id: invite.partnerId } });
392	  if (!partner) return { error: "That partner record no longer exists." };
393	  if (partner.userId) return { error: "This partner already has a login. Sign in instead." };
394	
395	  const existing = await db.user.findUnique({ where: { email: invite.email }, select: { id: true } });
396	  if (existing) {
397	    return { error: "An account with that email already exists. Sign in and contact support to link it." };
398	  }
399	
400	  const user = await db.$transaction(async (tx) => {
401	    const created = await tx.user.create({
402	      data: {
403	        email: invite.email,
404	        name,
405	        passwordHash: await bcrypt.hash(password, 12),
406	      },
407	    });
408	    // Guarded: if the code raced with `adminCreatePartner`'s own linkEmail path,
409	    // the unique `userId` on ReferralPartner stops a partner ever being linked
410	    // to two accounts (the update simply fails to find a still-unlinked row).
411	    const linked = await tx.referralPartner.updateMany({
412	      where: { id: invite.partnerId, userId: null },
413	      data: { userId: created.id },
414	    });
415	    if (linked.count !== 1) throw new Error("PARTNER_ALREADY_LINKED");
416	    await tx.partnerInvite.update({ where: { id: invite.id }, data: { acceptedAt: new Date() } });
417	    return created;
418	  }).catch((e) => {
419	    if (e instanceof Error && e.message === "PARTNER_ALREADY_LINKED") return null;
420	    throw e;
421	  });
422	
423	  if (!user) return { error: "This partner already has a login. Sign in instead." };
424	
425	  await db.auditLog.create({
426	    data: { userId: user.id, action: "partner.invite_accepted", detail: partner.code },
427	  });
428	  await createSession(user.id);
429	  redirect("/dashboard/partner");
430	}
