/**
 * Nxeon transactional email catalog.
 *
 * Every customer-facing transactional email the platform can send, rendered
 * synchronously as `{ template, subject, html }`. Templates compose the shared
 * inline-styled components from `lib/email-render` and wrap them in the branded
 * shell, so every message is visually consistent and email-client safe.
 *
 * The `template` field on each result maps the message onto its DB template key
 * (used for EmailLog attribution and for a future migration to the DB-backed
 * editor). The existing six templates keep their exact original signatures so no
 * call site breaks; the rest are additive and ready to wire up.
 *
 * `emails` is re-exported from `lib/mailer` for backward compatibility, so all
 * existing `import { emails } from "@/lib/mailer"` call sites keep working.
 */

import {
  appUrl,
  wrapEmail,
  emailButton,
  emailHeading,
  emailParagraph,
  emailEyebrow,
  emailNote,
  emailPanel,
  emailBanner,
  emailKeyValue,
  emailList,
  emailCode,
  emailDivider,
  BRAND,
  type Accent,
} from "@/lib/email-render";

/** Font stack mirrored from lib/email-render (kept private there). */
const EMAIL_FONT = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const escHtml = (s: unknown) =>
  String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

export type BuiltEmail = { template: string; subject: string; html: string };

const url = () => appUrl();
const path = (p: string) => `${url()}${p}`;

// Common dashboard deep links.
const LINKS = {
  dashboard: () => path("/dashboard"),
  deploy: () => path("/dashboard/deploy"),
  servers: () => path("/dashboard/servers"),
  billing: () => path("/dashboard/billing"),
  invoices: () => path("/dashboard/invoices"),
  domains: () => path("/dashboard/domains"),
  ssl: () => path("/dashboard/ssl"),
  email: () => path("/dashboard/email"),
  support: () => path("/dashboard/support"),
  team: () => path("/dashboard/team"),
  volumes: () => path("/dashboard/volumes"),
  affiliate: () => path("/dashboard/affiliate"),
  refer: () => path("/dashboard/refer"),
  security: () => path("/dashboard/settings"),
};

/**
 * Compose a standard transactional email from structured parts. Keeps every
 * template terse and uniform: eyebrow → heading → body blocks → optional CTA →
 * optional footnote, all wrapped with a preheader.
 */
function build(opts: {
  template: string;
  subject: string;
  preheader: string;
  eyebrow?: string;
  accent?: Accent;
  heading: string;
  blocks: string[];
  cta?: { href: string; label: string; accent?: Accent };
  note?: string;
}): BuiltEmail {
  const parts: string[] = [];
  if (opts.eyebrow) parts.push(emailEyebrow(opts.eyebrow, opts.accent ?? "violet"));
  parts.push(emailHeading(opts.heading));
  parts.push(...opts.blocks);
  if (opts.cta) parts.push(emailButton(opts.cta.href, opts.cta.label, opts.cta.accent ?? "violet"));
  if (opts.note) parts.push(emailNote(opts.note));
  return {
    template: opts.template,
    subject: opts.subject,
    html: wrapEmail(parts.join("\n"), { preheader: opts.preheader }),
  };
}

