// Creator Partner Program — rules for a SELF-CHOSEN sponsor code (2026-09-27).
//
// Pure and DB-free, so the claim page can give instant feedback while typing
// and the server action re-runs the exact same checks (never trust the
// client). The DB-side collision checks (other partners, coupons, peer
// referral codes) live in lib/actions-partner-invite.ts.
//
// CASE: codes are CASE-INSENSITIVE and stored in ONE canonical form —
// UPPERCASE. That matches everything that already reads a partner code:
// app/partner/[code]/route.ts and lib/actions.ts register() both upper-case
// the incoming code, and lib/actions-partner.ts normalizeCode stores admin-made
// codes upper-cased. So /partner/sam, /partner/SAM and ?ref=Sam all resolve to
// the partner whose code is SAM.
//
// LENGTH: 3–8 characters, letters and digits only — applies to NEW self-chosen
// codes only. Existing (admin-made) codes are never re-validated against this,
// so e.g. a longer or dashed legacy code keeps working unchanged.

export const SPONSOR_CODE_MIN = 3;
export const SPONSOR_CODE_MAX = 8;

export function canonicalSponsorCode(raw: string): string {
  return raw.trim().toUpperCase();
}

/** Words that would read as Nxeon itself, staff, or a system address. Exact match. */
const RESERVED = new Set([
  "ADMIN", "ADMINS", "NXEON", "NEXION", "STAFF", "SUPPORT", "TEST", "TESTING", "ROOT", "SYSTEM",
  "BILLING", "HELP", "HELPDESK", "OFFICIAL", "OWNER", "SECURITY", "SECURE", "API", "WWW", "MAIL",
  "EMAIL", "PARTNER", "PARTNERS", "INVITE", "CLAIM", "NULL", "UNDEFINED", "NONE", "KODELY",
  "TEAM", "SALES", "ABUSE", "LEGAL", "REFUND", "REFUNDS", "PAYPAL", "STRIPE", "WISE", "DISCORD",
  "FREE", "PROMO", "COUPON", "CODE", "DISCOUNT", "STAGING", "DEV", "MOD", "MODS", "MODERATOR",
  "SERVER", "SERVERS", "STATUS", "LOGIN", "SIGNUP", "REGISTER", "ACCOUNT", "WALLET", "PAYOUT",
  "CEO", "FOUNDER", "HOSTMASTER", "POSTMASTER", "WEBMASTER", "NOREPLY", "DEMO", "SAMPLE",
]);

/** Substrings that imply being Nxeon / its staff wherever they appear. */
const IMPERSONATION_PARTS = ["NXEON", "NEXION", "ADMIN", "STAFF", "SUPPORT", "OFFICIAL", "MODERATOR"];

/** Unambiguous profanity/slurs — blocked as a substring. */
const PROFANE_PARTS = ["FUCK", "SHIT", "CUNT", "NIGG", "FAGGOT", "BITCH", "WHORE", "HITLER", "NAZI", "PENIS", "VAGINA", "RETARD"];
/** Short words that are only offensive on their own (a substring match would block e.g. GRAPE). */
const PROFANE_WHOLE = new Set(["FAG", "FAGS", "RAPE", "RAPIST", "DICK", "COCK", "PUSSY", "SLUT", "PORN", "SEX", "SEXY", "ASS", "ASSHOLE", "KKK", "TWAT", "WANK", "WANKER", "CUM", "NSFW", "XXX", "HOE", "HOES", "DAMN", "PISS", "TITS"]);

/** Undo the common look-alike swaps so N3X0N / ADM1N / F4G are caught too. */
function deLeet(s: string): string {
  return s.replace(/0/g, "O").replace(/1/g, "I").replace(/3/g, "E").replace(/4/g, "A").replace(/5/g, "S").replace(/7/g, "T").replace(/8/g, "B").replace(/9/g, "G");
}

export type CodeCheck = { ok: true; code: string } | { ok: false; code: string; reason: string };

/** Format + reserved + impersonation + profanity. Does NOT check availability. */
export function checkSponsorCodeFormat(raw: string): CodeCheck {
  const code = canonicalSponsorCode(raw);
  if (!code) return { ok: false, code, reason: "Choose a code." };
  if (!/^[A-Z0-9]+$/.test(code)) return { ok: false, code, reason: "Letters and numbers only — no spaces, dashes or symbols." };
  if (code.length < SPONSOR_CODE_MIN) return { ok: false, code, reason: `At least ${SPONSOR_CODE_MIN} characters.` };
  if (code.length > SPONSOR_CODE_MAX) return { ok: false, code, reason: `At most ${SPONSOR_CODE_MAX} characters.` };
  if (/^[0-9]+$/.test(code)) return { ok: false, code, reason: "Include at least one letter." };

  const forms = [code, deLeet(code), code.replace(/1/g, "L")];
  if (forms.some((f) => RESERVED.has(f))) return { ok: false, code, reason: "That code is reserved." };
  if (forms.some((f) => IMPERSONATION_PARTS.some((p) => f.includes(p)))) {
    return { ok: false, code, reason: "Codes can't suggest they belong to Nxeon or its staff." };
  }
  if (forms.some((f) => PROFANE_WHOLE.has(f) || PROFANE_PARTS.some((p) => f.includes(p)))) {
    return { ok: false, code, reason: "Please choose a different code." };
  }
  return { ok: true, code };
}

