"use server";

// Creator Partner Program — CREATOR invites (2026-09-27).
//
// Extends the existing PartnerInvite mechanism (lib/actions-partner.ts —
// token → SHA-256 hash at rest, single use, expiry, revoke) with a second
// kind, "CREATOR": the admin invites a creator by EMAIL before any partner
// record exists; the creator claims it from their own signed-in account at
// /partner/claim?token=… and chooses their own sponsor code there
// (lib/partner-code.ts). The claim creates their ReferralPartner.
//
// Decisions (documented in docs/DOCUMENTATION.md, Creator Partner Program):
//  - EMAIL MATCH: the claiming account's email must equal the invited email,
//    unless the admin ticked "allow a different email" on the invite
//    (PartnerInvite.allowAnyEmail). The token alone is a bearer secret in an
//    inbox; the email match means a forwarded/leaked link can't be claimed by
//    someone else's account.
//  - CODES are case-insensitive, stored UPPERCASE, 3–8 letters/digits, and
//    must not collide (case-insensitively) with another partner code, a
//    coupon code, or any customer's peer-referral code — the register flow
//    resolves a `ref` against partner codes FIRST, so colliding with a
//    customer's referral code would silently hijack that customer's link.
//  - Resend ROTATES the token (old link dies) and resets the expiry.
//  - Staging has no SMTP configured, so sendMail returns false there and the
//    admin gets the one-time link to copy instead (also useful in production
//    for a creator contacted by DM).

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { headers } from "next/headers";
import { randomBytes, createHash } from "node:crypto";
import { db } from "./db";
import { requireArea } from "./rbac";
import { requireUser, assertNotImpersonating } from "./auth";
import { checkRateLimit, clientIp } from "./rate-limit";
import { checkSponsorCodeFormat } from "./partner-code";

const DEFAULT_RATE = 40; // the program's published lifetime rate
const DEFAULT_TTL_DAYS = 14;
const MAX_BATCH = 25;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const hashToken = (t: string) => createHash("sha256").update(t).digest("hex");
const appBase = () => (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/+$/, "");
const claimUrl = (token: string) => `${appBase()}/partner/claim?token=${encodeURIComponent(token)}`;

async function sendInviteEmail(inv: { email: string; name: string | null; ratePct: number | null; expiresAt: Date; allowAnyEmail: boolean }, token: string): Promise<boolean> {
  const { sendMail, emails } = await import("./mailer");
  const tpl = emails.creatorPartnerInvite({
    name: inv.name,
    email: inv.email,
    ratePct: inv.ratePct ?? DEFAULT_RATE,
    claimUrl: claimUrl(token),
    expires: inv.expiresAt.toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric", timeZone: "UTC" }),
    anyEmail: inv.allowAnyEmail,
  });
  return sendMail({ to: inv.email, subject: tpl.subject, html: tpl.html, template: tpl.template });
}

// ---------- Admin: invite creators ----------

export type InviteResult = { email: string; status: "sent" | "created" | "skipped"; link?: string; reason?: string };
export type InviteCreatorsState = { error?: string; results?: InviteResult[] };

export async function adminInviteCreators(_prev: InviteCreatorsState, fd: FormData): Promise<InviteCreatorsState> {
  const admin = await requireArea("billing");

  const emails = [...new Set(
    String(fd.get("emails") ?? "")
      .split(/[\s,;]+/)
      .map((e) => e.trim().toLowerCase())
      .filter(Boolean)
  )];
  if (emails.length === 0) return { error: "Enter at least one email address." };
  if (emails.length > MAX_BATCH) return { error: `At most ${MAX_BATCH} invites at a time.` };
  const bad = emails.filter((e) => !EMAIL_RE.test(e) || e.length > 200);
  if (bad.length) return { error: `Not a valid email: ${bad.slice(0, 3).join(", ")}` };

  const name = String(fd.get("name") ?? "").trim().slice(0, 120) || null;
  const note = String(fd.get("note") ?? "").trim().slice(0, 500) || null;
  const rateRaw = Number(fd.get("ratePct") ?? DEFAULT_RATE);
  const ratePct = Number.isFinite(rateRaw) ? Math.min(90, Math.max(1, Math.round(rateRaw * 100) / 100)) : DEFAULT_RATE;
  const daysRaw = Number(fd.get("expiryDays") ?? DEFAULT_TTL_DAYS);
  const days = Number.isFinite(daysRaw) ? Math.min(30, Math.max(1, Math.round(daysRaw))) : DEFAULT_TTL_DAYS;
  const allowAnyEmail = fd.get("allowAnyEmail") === "on";

  const results: InviteResult[] = [];
  for (const email of emails) {
    const existingUser = await db.user.findUnique({ where: { email }, select: { id: true, partnerAccount: { select: { code: true } } } });
    if (existingUser?.partnerAccount) {
      results.push({ email, status: "skipped", reason: `already a partner (${existingUser.partnerAccount.code})` });
      continue;
    }
    const pending = await db.partnerInvite.findFirst({
      where: { kind: "CREATOR", email, acceptedAt: null, revokedAt: null, expiresAt: { gt: new Date() } },
      select: { id: true },
    });
    if (pending) {
      results.push({ email, status: "skipped", reason: "already has a pending invite — use Resend" });
      continue;
    }

    const token = randomBytes(32).toString("base64url");
    const now = new Date();
    const inv = await db.partnerInvite.create({
      data: {
        kind: "CREATOR",
        email,
        tokenHash: hashToken(token),
        invitedById: admin.id,
        expiresAt: new Date(now.getTime() + days * 86_400_000),
        name: emails.length === 1 ? name : null,
        note,
        ratePct,
        allowAnyEmail,
        lastSentAt: now,
      },
    });
    const sent = await sendInviteEmail(inv, token);
    await db.auditLog.create({
      data: { userId: admin.id, action: "partner.creator_invite", detail: `${email} @ ${ratePct}%${sent ? "" : " (email not sent)"}` },
    });
    results.push({ email, status: sent ? "sent" : "created", link: claimUrl(token) });
  }

  revalidatePath("/admin/partners");
  return { results };
}

export async function adminResendCreatorInvite(inviteId: string): Promise<{ error?: string; ok?: boolean; sent?: boolean; link?: string }> {
  const admin = await requireArea("billing");
  const inv = await db.partnerInvite.findUnique({ where: { id: inviteId } });
  if (!inv || inv.kind !== "CREATOR") return { error: "Invite not found." };
  if (inv.acceptedAt) return { error: "This invite has already been claimed." };
  if (inv.revokedAt) return { error: "This invite was revoked — send a new one instead." };

  const token = randomBytes(32).toString("base64url");
  const now = new Date();
  const updated = await db.partnerInvite.update({
    where: { id: inv.id },
    data: {
      tokenHash: hashToken(token), // rotates: the previous link stops working
      expiresAt: new Date(now.getTime() + DEFAULT_TTL_DAYS * 86_400_000),
      lastSentAt: now,
      sendCount: { increment: 1 },
    },
  });
  const sent = await sendInviteEmail(updated, token);
  await db.auditLog.create({
    data: { userId: admin.id, action: "partner.creator_invite_resent", detail: `${inv.email}${sent ? "" : " (email not sent)"}` },
  });
  revalidatePath("/admin/partners");
  return { ok: true, sent, link: claimUrl(token) };
}

// ---------- Creator: check + claim ----------

async function loadClaimableInvite(token: string) {
  if (!token || token.length > 200) return { error: "This invitation link is invalid." } as const;
  const inv = await db.partnerInvite.findUnique({ where: { tokenHash: hashToken(token) } });
  if (!inv || inv.kind !== "CREATOR") return { error: "This invitation link is invalid." } as const;
  if (inv.revokedAt) return { error: "This invitation has been cancelled. Ask us for a new one." } as const;
  if (inv.acceptedAt) return { error: "This invitation has already been claimed." } as const;
  if (inv.expiresAt < new Date()) return { error: "This invitation has expired. Ask us to resend it." } as const;
  return { inv } as const;
}

/** Case-insensitive collision with any code a `ref`/checkout path could resolve. */
async function codeTaken(code: string): Promise<string | null> {
  const eq = { equals: code, mode: "insensitive" as const };
  const [partner, coupon, referral] = await Promise.all([
    db.referralPartner.findFirst({ where: { code: eq }, select: { id: true } }),
    db.coupon.findFirst({ where: { code: eq }, select: { id: true } }),
    db.user.findFirst({ where: { referralCode: eq }, select: { id: true } }),
  ]);
  if (partner || coupon || referral) return "That code is already taken.";
  return null;
}

export type CodeAvailability = { ok: boolean; code: string; reason?: string };

/** Live availability for the claim page. Only answers for a holder of a valid invite. */
