"use client";

import { useActionState } from "react";
import { acceptPartnerInvite } from "@/lib/actions-partner";

/**
 * The Creator Partner Program's partner-login-invite acceptance form — the
 * counterpart to RegisterForm (components/AuthForms.tsx), but for someone
 * redeeming an admin-sent invite token instead of signing up cold. On success
 * `acceptPartnerInvite` redirects server-side to /dashboard/partner; this
 * component only ever renders the form or an inline error.
 */
export function PartnerInviteAcceptForm({ token, email }: { token: string; email: string }) {
  const [state, action, pending] = useActionState(acceptPartnerInvite, {});
  return (
    <form action={action} className="space-y-4">
      <input type="hidden" name="token" value={token} />
      {state?.error ? (
        <div role="alert" className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {state.error}
        </div>
      ) : null}
      <div>
        <label className="label" htmlFor="invite-email">Email</label>
        <input id="invite-email" className="input" value={email} disabled readOnly />
      </div>
      <div>
        <label className="label" htmlFor="invite-name">Your name</label>
        <input id="invite-name" className="input" name="name" required autoComplete="name" autoFocus />
      </div>
      <div>
        <label className="label" htmlFor="invite-password">Choose a password</label>
        <input
          id="invite-password"
          className="input"
          name="password"
          type="password"
          required
          minLength={8}
          autoComplete="new-password"
        />
        <p className="mt-1 text-xs text-slate-500">At least 8 characters, with a letter and a number.</p>
      </div>
      <button className="btn-primary w-full" disabled={pending} type="submit">
        {pending ? "Setting up your account…" : "Set up your Partner account"}
      </button>
    </form>
  );
}
