import { createHash } from "node:crypto";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { AuthShell } from "@/components/marketing/AuthShell";
import { CreatorClaimForm } from "@/components/customer/CreatorClaimForm";

export const dynamic = "force-dynamic";

/**
 * Claim page for a Creator Partner invite (nxeon.cloud/partner/claim?token=…),
 * emailed by adminInviteCreators (lib/actions-partner-invite.ts).
 *
 * Read-only on load — nothing is consumed until the creator submits their
 * code (claimCreatorInvite). Signed out → register / sign in first, then come
 * straight back here: the token rides in `next=` (validated by safeNext on
 * both forms, same as every other deep link into the app).
 */
export default async function CreatorClaimPage({ searchParams }: { searchParams: Promise<{ token?: string }> }) {
  const { token } = await searchParams;
  const bullets = [
    "Choose your own sponsor code — your link becomes /partner/YOURCODE",
    "Your audience gets 50% off their first purchase and 10% off every purchase after",
    "Real-time clicks, signups, paying customers and commission in your dashboard",
  ];

  const invite = token
    ? await db.partnerInvite.findUnique({ where: { tokenHash: createHash("sha256").update(token).digest("hex") } })
    : null;
  const problem = !token || !invite || invite.kind !== "CREATOR"
    ? "This invitation link is invalid. Ask whoever sent it for a fresh one."
    : invite.revokedAt
      ? "This invitation has been cancelled. Ask us for a new one."
      : invite.acceptedAt
        ? "This invitation has already been claimed."
        : invite.expiresAt < new Date()
          ? "This invitation has expired. Ask us to resend it."
          : null;

  if (problem || !invite || !token) {
    return (
      <AuthShell heading="Invitation unavailable" sub={problem ?? "Something went wrong."} bullets={[]}>
        <a href="/dashboard/partner" className="text-sm font-semibold text-brand-300 hover:underline">Go to the Partner Program</a>
      </AuthShell>
    );
  }

  const rate = invite.ratePct ?? 40;
  const heading = "Join the Nxeon Creator Partner Program";
  const sub = `Earn ${rate}% of every qualifying charge from the customers you bring — their first order and every renewal, for as long as they stay.`;
  const back = `/partner/claim?token=${encodeURIComponent(token)}`;
  const user = await currentUser();

  if (!user) {
    return (
      <AuthShell heading={heading} sub={sub} bullets={bullets}>
        <div className="space-y-4">
          <p className="text-sm text-slate-300">
            {invite.allowAnyEmail ? (
              <>Sign in to your Nxeon account — or create one — to claim this invite.</>
            ) : (
              <>This invite is for <b className="text-white">{invite.email}</b>. Create an Nxeon account with that address, or sign in if you already have one.</>
            )}
          </p>
          <a href={`/register?next=${encodeURIComponent(back)}`} className="btn-primary w-full justify-center">Create my account</a>
          <a href={`/login?next=${encodeURIComponent(back)}`} className="btn-secondary w-full justify-center">I already have an account — sign in</a>
        </div>
      </AuthShell>
    );
  }

  const partner = await db.referralPartner.findUnique({ where: { userId: user.id }, select: { code: true } });
  const emailMismatch = !invite.allowAnyEmail && user.email.toLowerCase() !== invite.email.toLowerCase();

  return (
    <AuthShell heading={heading} sub={sub} bullets={bullets}>
      {partner ? (
        <div className="space-y-3">
          <p className="text-sm text-slate-300">Your account is already a partner, with code <b className="font-mono text-white">{partner.code}</b>.</p>
          <a href="/dashboard/partner" className="btn-primary w-full justify-center">Open your partner dashboard</a>
        </div>
      ) : emailMismatch ? (
        <div className="space-y-3">
          <div role="alert" className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-sm text-amber-200">
            This invite was sent to <b>{invite.email}</b>, but you&apos;re signed in as <b>{user.email}</b>. Sign out and
            use the invited address, or ask us to send the invite to this one.
          </div>
          <a href="/dashboard" className="text-sm font-semibold text-brand-300 hover:underline">Back to your dashboard</a>
        </div>
      ) : (
        <CreatorClaimForm token={token} email={user.email} />
      )}
    </AuthShell>
  );
}
