"use client";

import { useActionState, useState, useTransition } from "react";
import { adminInviteCreators, adminResendCreatorInvite, type InviteCreatorsState } from "@/lib/actions-partner-invite";

/* Admin: invite creators to the Creator Partner Program by email — they claim
 * the invite from their own account and choose their own sponsor code
 * (lib/actions-partner-invite.ts). A claim link is shown ONCE here right after
 * creating/resending (only its hash is stored), so an invite can also be
 * delivered by DM, and so staging — which has no SMTP — can still be tested. */

function CopyLink({ link }: { link: string }) {
  const [done, setDone] = useState(false);
  return (
    <span className="flex min-w-0 items-center gap-2">
      <input readOnly value={link} onFocus={(e) => e.currentTarget.select()} className="input h-8 min-w-0 flex-1 font-mono text-xs" />
      <button
        type="button"
        className="btn-secondary h-8 px-2.5 text-xs"
        onClick={async () => {
          try { await navigator.clipboard.writeText(link); setDone(true); setTimeout(() => setDone(false), 1500); } catch { /* select + copy manually */ }
        }}
      >
        {done ? "Copied" : "Copy"}
      </button>
    </span>
  );
}

export function InviteCreatorsForm() {
  const [state, action, pending] = useActionState(adminInviteCreators, {} as InviteCreatorsState);
  return (
    <form action={action} className="space-y-3">
      {state.error && (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{state.error}</div>
      )}
      <div className="grid gap-3 sm:grid-cols-2">
        <div className="sm:col-span-2">
          <label className="label">Creator email(s)</label>
          <textarea
            name="emails"
            rows={2}
            className="input w-full font-mono text-sm"
            placeholder="creator@example.com — several? one per line or comma-separated (max 25)"
            required
          />
        </div>
        <div>
          <label className="label">Name / channel (optional, single invite)</label>
          <input name="name" className="input w-full" placeholder="Sam Plays" maxLength={120} />
        </div>
        <div>
          <label className="label">Internal note (optional)</label>
          <input name="note" className="input w-full" placeholder="YouTube, ~40k subs, met at …" maxLength={500} />
        </div>
        <div>
          <label className="label">Commission rate (%)</label>
          <input name="ratePct" type="number" min="1" max="90" step="0.5" defaultValue="40" className="input w-full" required />
        </div>
        <div>
          <label className="label">Link expires after (days)</label>
          <input name="expiryDays" type="number" min="1" max="30" step="1" defaultValue="14" className="input w-full" required />
        </div>
        <label className="flex items-start gap-2 text-sm text-slate-300 sm:col-span-2">
          <input type="checkbox" name="allowAnyEmail" className="mt-1" />
          <span>
            Allow claiming from an account with a <b>different</b> email address (admin override). Leave off unless the
            creator told you they&apos;ll sign up with another address — by default the claiming account must use the invited email.
          </span>
        </label>
      </div>
      <button className="btn-primary" disabled={pending}>{pending ? "Sending…" : "Send invite(s)"}</button>
      {state.results && state.results.length > 0 && (
        <ul className="space-y-2 rounded-lg border border-slate-800 p-3 text-sm">
          {state.results.map((r) => (
            <li key={r.email} className="space-y-1">
              <div>
                <span className="font-mono text-slate-200">{r.email}</span>{" "}
                {r.status === "sent" && <span className="text-emerald-400">— invite emailed</span>}
                {r.status === "created" && <span className="text-amber-300">— invite created, but the email could not be sent (mail not configured?). Send this link yourself:</span>}
                {r.status === "skipped" && <span className="text-slate-400">— skipped: {r.reason}</span>}
              </div>
              {r.link && <CopyLink link={r.link} />}
            </li>
          ))}
          <li className="text-xs text-slate-500">Links are shown once — only a hash is stored. Use Resend to issue a new one.</li>
        </ul>
      )}
    </form>
  );
}

export function ResendCreatorInviteButton({ inviteId }: { inviteId: string }) {
  const [pending, start] = useTransition();
  const [res, setRes] = useState<{ error?: string; sent?: boolean; link?: string } | null>(null);
  return (
    <span className="inline-flex flex-col items-end gap-1">
      <button
        type="button"
        className="text-xs font-semibold text-brand-300 hover:underline disabled:opacity-50"
        disabled={pending}
        onClick={() => {
          if (!confirm("Resend this invite? A new link is issued and the previous one stops working.")) return;
          start(async () => setRes(await adminResendCreatorInvite(inviteId)));
        }}
      >
        {pending ? "Sending…" : "Resend"}
      </button>
      {res?.error && <span className="text-xs text-red-400">{res.error}</span>}
      {res?.link && (
        <span className="w-[320px] max-w-[70vw] text-left">
          <span className={"block text-xs " + (res.sent ? "text-emerald-400" : "text-amber-300")}>
            {res.sent ? "Emailed. New link:" : "Email not sent — send this link yourself:"}
          </span>
          <CopyLink link={res.link} />
        </span>
      )}
    </span>
  );
}
