const OUT = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/partner";
const SITE = "https://staging.nxeon.cloud";
const ADMIN = "https://staging.4j3d7gkr2wcbi34.nxeon.cloud";
const creds = fs.readFileSync("/root/nxeon-staging-credentials.txt", "utf8");
const adminEmail = creds.match(/Email:\s*(\S+)/)[1];
const adminPass = creds.match(/Password:\s*(\S+)/)[1];

const stamp = Date.now().toString(36);
const creatorEmail = `creator-test-${stamp}@example.com`;
const creatorPass = `Stg!${stamp}9x`;
const code = ("TC" + stamp.slice(-4)).toUpperCase().replace(/[^A-Z0-9]/g, "X").slice(0, 8);
const log = (...a) => console.log(...a);
const results = { creatorEmail, code, checks: [] };
const check = (name, ok, detail = "") => { results.checks.push({ name, ok, detail }); log(ok ? "PASS" : "FAIL", name, detail); };

async function shot(page, name, full = true) {
  await page.waitForTimeout(500);
  await page.screenshot({ path: `${OUT}/${name}.png`, fullPage: full });
}

async function dismissConsent(page) {
  const b = page.locator('button:has-text("Accept")');
  if (await b.count()) await b.first().click().catch(() => {});
}

(async () => {
  const browser = await chromium.launch();
  try {
    // ---------- 1. Admin invites a creator ----------
    const admin = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
    const ap = await admin.newPage();
    await ap.goto(`${ADMIN}/admin/login`, { waitUntil: "networkidle" });
    await ap.fill('input[name="email"]', adminEmail);
    await ap.fill('input[name="password"]', adminPass);
    await ap.click('button:has-text("Sign in")');
    await ap.waitForURL(/\/admin(?!\/login)/, { timeout: 20000 });
    await ap.goto(`${ADMIN}/admin/partners`, { waitUntil: "networkidle" });
    await ap.fill('textarea[name="emails"]', creatorEmail);
    await ap.fill('input[name="name"]', "Test Creator (staging)");
    await ap.fill('input[name="note"]', "Staging verification — example.com test address, never delivered");
    await ap.click('button:has-text("Send invite(s)")');
    const linkInput = ap.locator('input[readonly][value*="/partner/claim?token="]').first();
    await linkInput.waitFor({ timeout: 20000 });
    const claimLink = await linkInput.inputValue();
    check("admin invite created + one-time link shown", claimLink.includes("/partner/claim?token="));
    // Blur the token in the screenshot: replace the value before shooting.
    await linkInput.evaluate((el) => { el.value = el.value.replace(/token=.*/, "token=•••••••• (redacted in screenshot)"); });
    await shot(ap, "admin-invite-created-1440");

    // ---------- 2. Creator claims ----------
    const cr = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
    const cp = await cr.newPage();
    await cp.goto(claimLink, { waitUntil: "networkidle" });
    await dismissConsent(cp);
    check("claim page (signed out) offers register/login", (await cp.locator('a:has-text("Create my account")').count()) === 1);
    await shot(cp, "claim-signed-out-1440", false);
    await cp.setViewportSize({ width: 390, height: 844 });
    await shot(cp, "claim-signed-out-390", false);
    await cp.setViewportSize({ width: 1440, height: 1000 });
    await cp.click('a:has-text("Create my account")');
    await cp.waitForURL(/\/register/, { timeout: 15000 });
    check("register link carries next=/partner/claim", decodeURIComponent(cp.url()).includes("next=/partner/claim?token="));
    await cp.fill("#register-name", "Test Creator");
    await cp.fill("#register-email", creatorEmail);
    await cp.fill("#register-password", creatorPass);
    await cp.click('button:has-text("Create account")');
    await cp.waitForURL(/\/partner\/claim/, { timeout: 25000 });
    await cp.waitForSelector("#claim-code", { timeout: 15000 });
    check("after register, landed back on claim page with code picker", true);

    // Rejections: reserved, impersonation, length
    for (const [bad, expect] of [["ADMIN", "reserved"], ["NXEONPRO", "Nxeon"], ["AB", "At least"]]) {
      await cp.fill("#claim-code", bad);
      await cp.waitForTimeout(700);
      const t = await cp.locator("#claim-code-status").innerText();
      check(`code "${bad}" rejected`, t.includes(expect), t);
    }
    await cp.fill("#claim-code", "admin");
    await cp.waitForTimeout(600);
    await shot(cp, "claim-code-rejected-1440", false);
    await cp.fill("#claim-code", code.toLowerCase());
    await cp.waitForFunction(() => /available|taken/.test(document.querySelector("#claim-code-status")?.textContent || ""), null, { timeout: 15000 });
    const availText = await cp.locator("#claim-code-status").innerText();
    check(`code ${code} available (typed lowercase, shown uppercase)`, availText.includes(`${code} is available`), availText);
    await shot(cp, "claim-code-available-1440", false);
    await cp.setViewportSize({ width: 390, height: 844 });
    await shot(cp, "claim-code-available-390", false);
    await cp.setViewportSize({ width: 1440, height: 1000 });
    await cp.click('button:has-text("Claim my partner account")');
    await cp.waitForURL(/\/dashboard\/partner\?tab=settings/, { timeout: 25000 });
    check("claim redirected to partner settings tab", cp.url().includes("welcome=1"));

    // ---------- 3. Real traffic through the new code ----------
    // A click with a referer (top sources) and one without, then one signup through the link.
    const v = await browser.newContext({ extraHTTPHeaders: { referer: "https://www.youtube.com/watch?v=staging-test" } });
    const vp = await v.newPage();
    await vp.goto(`${SITE}/partner/${code.toLowerCase()}`, { waitUntil: "domcontentloaded" });
    check("lowercase /partner/<code> link resolves to register", vp.url().includes("/register"));
    await v.close();
    const v2 = await browser.newContext();
    const vp2 = await v2.newPage();
    await vp2.goto(`${SITE}/partner/${code}`, { waitUntil: "networkidle" });
    await vp2.fill("#register-name", "Referred Test");
    await vp2.fill("#register-email", `referred-test-${stamp}@example.com`);
    await vp2.fill("#register-password", creatorPass);
    await vp2.click('button:has-text("Create account")');
    await vp2.waitForURL(/\/dashboard/, { timeout: 25000 });
    await v2.close();

    // ---------- 4. Settings: contact + payout ----------
    await cp.goto(`${SITE}/dashboard/partner?tab=settings&welcome=1`, { waitUntil: "networkidle" });
    await dismissConsent(cp);
    await shot(cp, "tab-settings-welcome-1440");
    await cp.fill('input[name="contactName"]', "Test Creator");
    await cp.fill('input[name="contactEmail"]', "not-an-email");
    await cp.click('button:has-text("Save contact details")');
    await cp.waitForTimeout(1200);
    check("invalid contact email rejected", (await cp.locator("text=Enter a valid contact email").count()) > 0);
    await cp.fill('input[name="contactEmail"]', creatorEmail);
    await cp.fill('input[name="discord"]', "testcreator");
    await cp.fill('input[name="social"]', "youtube.com/@testcreator");
    await cp.click('button:has-text("Save contact details")');
    await cp.waitForSelector("text=Saved ✓", { timeout: 15000 });
    check("contact saved", true);
    await cp.click('label:has-text("Bank transfer")');
    await cp.fill('input[name="accountName"]', "Test Creator");
    await cp.click('button:has-text("Save payout method")');
    await cp.waitForTimeout(1200);
    check("bank without IBAN/account rejected", (await cp.locator("text=Enter an IBAN").count()) > 0);
    await cp.click('label:has-text("PayPal")');
    await cp.fill('input[name="paypalEmail"]', `paypal-${stamp}@example.com`);
    await cp.fill('textarea[name="note"]', "USD please");
    await cp.click('button:has-text("Save payout method")');
    await cp.waitForSelector("text=PayPal · p•••@example.com", { timeout: 15000 });
    const html = await cp.content();
    check("partner sees masked summary only (full PayPal email not in page)", !html.includes(`paypal-${stamp}@example.com`));
    await shot(cp, "tab-settings-saved-1440");

    // ---------- 5. Every tab at 1440 and 390 ----------
    const tabs = ["overview", "analytics", "customers", "payouts", "media", "terms", "settings"];
    for (const w of [1440, 390]) {
      await cp.setViewportSize({ width: w, height: w === 390 ? 844 : 1000 });
      for (const t of tabs) {
        await cp.goto(`${SITE}/dashboard/partner?tab=${t}`, { waitUntil: "networkidle" });
        await dismissConsent(cp);
        const sel = await cp.locator(`#partner-tab-${t}`).getAttribute("aria-selected");
        const overflow = await cp.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
        check(`tab ${t} @${w} selected`, sel === "true");
        check(`tab ${t} @${w} no horizontal page overflow`, overflow <= 1, `overflow=${overflow}`);
        await shot(cp, `tab-${t}-${w}`);
      }
    }
    await cp.setViewportSize({ width: 1440, height: 1000 });

    // Keyboard: ArrowRight from Overview moves to Analytics and updates the URL.
    await cp.goto(`${SITE}/dashboard/partner`, { waitUntil: "networkidle" });
    await cp.focus("#partner-tab-overview");
    await cp.keyboard.press("ArrowRight");
    await cp.waitForTimeout(400);
    check("ArrowRight -> analytics tab + ?tab=analytics", cp.url().includes("tab=analytics") && (await cp.evaluate(() => document.activeElement?.id)) === "partner-tab-analytics");
    await cp.keyboard.press("End");
    await cp.waitForTimeout(300);
    check("End -> settings", cp.url().includes("tab=settings"));
    await cp.goBack();
    await cp.waitForTimeout(500);
    check("Back button returns to analytics", (await cp.locator("#partner-tab-analytics").getAttribute("aria-selected")) === "true");

    // Analytics range: 7d + custom
    await cp.goto(`${SITE}/dashboard/partner?tab=analytics&range=7d`, { waitUntil: "networkidle" });
    const body = await cp.locator('[role="tabpanel"]').innerText();
    check("analytics 7d shows the 2 real clicks", /\n2\nlink clicks/.test(body) || body.includes("2\nlink clicks"), body.slice(0, 200).replace(/\n/g, " | "));
    check("analytics shows youtube.com as a source", body.includes("youtube.com"));
    await cp.hover(".nx-partner-tabs"); // move pointer away
    const bars = cp.locator('[role="img"][aria-label^="Link clicks"]');
    const box = await bars.boundingBox();
    if (box) { await cp.mouse.move(box.x + box.width - 20, box.y + 80); await cp.waitForTimeout(300); }
    await shot(cp, "analytics-7d-hover-1440");
    await cp.click('button:has-text("Custom")');
    await cp.fill('input[type="date"] >> nth=0', "2026-09-01");
    await cp.click('button:has-text("Apply")');
    await cp.waitForURL(/range=custom/, { timeout: 15000 });
    await cp.waitForTimeout(800);
    check("custom range applied via URL", cp.url().includes("from=2026-09-01"));
    await shot(cp, "analytics-custom-1440");

    // Terms PDF route: none published -> 404 for partner
    const r = await cp.request.get(`${SITE}/api/creator-partner/terms`);
    check("terms PDF route 404 while unpublished", r.status() === 404, String(r.status()));

    // ---------- 6. Admin sees accepted invite + payout preference ----------
    await ap.goto(`${ADMIN}/admin/partners`, { waitUntil: "networkidle" });
    const row = ap.locator("tr", { hasText: creatorEmail });
    check("admin invite row shows accepted + code", (await row.innerText()).includes("accepted") && (await row.innerText()).includes(code));
    await shot(ap, "admin-partners-invites-1440");
    await row.locator(`a:has-text("${code}")`).click();
    await ap.waitForURL(/\/admin\/partners\/\w+/, { timeout: 15000 });
    const adminHtml = await ap.content();
    check("admin sees full PayPal email + note", adminHtml.includes(`paypal-${stamp}@example.com`) && adminHtml.includes("USD please"));
    await shot(ap, "admin-partner-detail-payout-1440");

    // Second claim with the same link must fail (single use)
    await cp.goto(claimLink, { waitUntil: "networkidle" });
    check("used link shows already-claimed", (await cp.locator("text=already been claimed").count()) > 0);
  } catch (e) {
    console.error("ERROR", e);
    results.error = String(e);
  } finally {
    fs.writeFileSync(`${OUT}/verify-results.json`, JSON.stringify(results, null, 2));
    await browser.close();
  }
})();

