    return {
/**
 * Render the TRIAL798 campaign email (lib/promo-trial-email.ts) to a local
 * HTML file for review — does not send anything. Uses a real existing
 * CUSTOMER-role user's id/name so the unsubscribe link and greeting are
 * genuine, not fixture data.
 *
 * Run:  npx tsx scripts/preview-promo-trial-email.ts [output.html]
 */
import { writeFileSync } from "node:fs";
import { db } from "../lib/db";
import { buildPromoTrialEmail } from "../lib/promo-trial-email";

async function main() {
  const outPath = process.argv[2] ?? "promo-trial-email-preview.html";

  const sample = await db.user.findFirst({
    where: { role: "CUSTOMER", name: { not: "" } },
    orderBy: { createdAt: "desc" },
    select: { id: true, name: true },
  });
  if (!sample) throw new Error("No CUSTOMER-role user found to render a sample against.");

  const { subject, html } = await buildPromoTrialEmail({ userId: sample.id, name: sample.name });

  writeFileSync(outPath, html, "utf8");
  console.log(`Subject: ${subject}`);
  console.log(`Rendered for: ${sample.name} (${sample.id})`);
  console.log(`Written to: ${outPath}`);
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error("Failed to render preview:", e);
    process.exit(1);
  });
