// Creator Partner Program — CREATOR invite core (2026-09-27). Plain server
// module (NOT "use server"): shared by the admin server actions
// (lib/actions-partner-invite.ts), the admin email-preview route
// (app/admin/partners/invite-preview/route.ts) and the batch script
// (scripts/partner-invite-batch.ts). Callers do their own auth.
//
// Lifecycle: DRAFT (created, `lastSentAt` null, token hash is a random value
// nobody holds — the invite cannot be claimed) -> SENT (an explicit admin Send
// rotates the token, sets the expiry, emails it) -> ACCEPTED / EXPIRED /
// REVOKED. Nothing in this module sends on creation.

import { randomBytes, createHash } from "node:crypto";
import { db } from "./db";
import { emails, type BuiltEmail } from "./email-templates";

export const CREATOR_DEFAULT_RATE = 40; // the program's published lifetime rate
export const CREATOR_INVITE_TTL_DAYS = 14;

export const hashInviteToken = (t: string) => createHash("sha256").update(t).digest("hex");
const appBase = () => (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/+$/, "");
export const creatorClaimUrl = (token: string) => `${appBase()}/partner/claim?token=${encodeURIComponent(token)}`;
/** Used for previews: a well-formed link whose token matches no invite. */
export const PREVIEW_TOKEN = "PREVIEW-ONLY-this-link-is-not-valid";

export type InviteState = "draft" | "sent" | "accepted" | "expired" | "revoked";
export function creatorInviteState(i: { acceptedAt: Date | null; revokedAt: Date | null; lastSentAt: Date | null; expiresAt: Date }, now = new Date()): InviteState {
  if (i.acceptedAt) return "accepted";
  if (i.revokedAt) return "revoked";
  if (!i.lastSentAt) return "draft";
  if (i.expiresAt < now) return "expired";
  return "sent";
}

// ---------- the owner's creator CSV ----------

/** One row of the owner's creator list. Header (case/space-insensitive):
 *  Name, Youtube Channel, Primary game, Email, Current Hosting Sponsor (If
 *  Applicable), Country, Subscriber count, Emailed. */
export type CreatorRow = {
  name: string;
  channel: string;
  game: string;
  email: string;
  country: string;
  subscribers: string;
};

/** Minimal RFC-4180 CSV parser (quoted fields, "" escapes, CRLF). */
function parseCsv(text: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let q = false;
  const s = text.replace(/^﻿/, "");
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (q) {
      if (ch === '"') {
        if (s[i + 1] === '"') { field += '"'; i++; } else q = false;
      } else field += ch;
    } else if (ch === '"') q = true;
    else if (ch === ",") { row.push(field); field = ""; }
    else if (ch === "\n" || ch === "\r") {
      if (ch === "\r" && s[i + 1] === "\n") i++;
      row.push(field); field = "";
      if (row.some((c) => c.trim() !== "")) rows.push(row);
      row = [];
    } else field += ch;
  }
  row.push(field);
  if (row.some((c) => c.trim() !== "")) rows.push(row);
  return rows;
}

export function parseCreatorCsv(text: string): { rows: CreatorRow[]; error?: string } {
  const all = parseCsv(text);
  if (all.length === 0) return { rows: [], error: "The CSV is empty." };
  const head = all[0].map((h) => h.trim().toLowerCase().replace(/\s+/g, " "));
  const col = (...names: string[]) => head.findIndex((h) => names.some((n) => h === n || h.startsWith(n)));
  const iEmail = col("email");
  const iName = col("name");
  if (iEmail < 0 || iName < 0) return { rows: [], error: "The CSV needs at least a Name and an Email column." };
  const iChannel = col("youtube channel", "channel");
  const iGame = col("primary game", "game");
  const iCountry = col("country");
  const iSubs = col("subscriber count", "subscribers");
  const get = (r: string[], i: number) => (i >= 0 ? (r[i] ?? "").trim() : "");
  const rows = all.slice(1).map((r) => ({
    name: get(r, iName),
    channel: get(r, iChannel),
    game: get(r, iGame),
    email: get(r, iEmail).toLowerCase(),
    country: get(r, iCountry),
    subscribers: get(r, iSubs),
  })).filter((r) => r.email);
  return { rows };
}

export function normalizeEmails(raw: string): { emails: string[]; invalid: string[] } {
  const list = [...new Set(raw.split(/[\s,;]+/).map((e) => e.trim().toLowerCase()).filter(Boolean))];
  const ok = (e: string) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e) && e.length <= 200;
  return { emails: list.filter(ok), invalid: list.filter((e) => !ok(e)) };
}

/** Match pasted emails to CSV rows — exact (case-insensitive) email match only, never a guess. */
export function matchCreators(emailsIn: string[], rows: CreatorRow[]): { matched: { email: string; row: CreatorRow }[]; unmatched: string[] } {
  const byEmail = new Map<string, CreatorRow>();
  for (const r of rows) if (!byEmail.has(r.email)) byEmail.set(r.email, r);
  const matched: { email: string; row: CreatorRow }[] = [];
  const unmatched: string[] = [];
  for (const e of emailsIn) {
    const r = byEmail.get(e);
    if (r) matched.push({ email: e, row: r }); else unmatched.push(e);
  }
  return { matched, unmatched };
}

/** Keep only http(s) links in the channel field (it is later rendered as a link). */
export function safeChannelUrl(v: string | null | undefined): string | null {
  const s = (v ?? "").trim();
  if (!s) return null;
  try {
    const u = new URL(s);
    return u.protocol === "https:" || u.protocol === "http:" ? u.toString().slice(0, 300) : null;
  } catch {
    return null;
  }
}

// ---------- drafts ----------

export type DraftEntry = {
  email: string;
  name?: string | null;
  channelUrl?: string | null;
  primaryGame?: string | null;
  country?: string | null;
  subscribers?: string | null;
};
export type DraftResult = { email: string; name: string | null; channel: string | null; status: "created" | "would create" | "skipped"; reason?: string };

/**
 * Create DRAFT creator invites. Never sends. Idempotent: an email that already
 * has a non-revoked CREATOR invite (draft, sent, accepted or expired), or whose
 * account is already a partner, is skipped.
 */
export async function createCreatorDrafts(
  entries: DraftEntry[],
  opts: { invitedById: string | null; ratePct?: number; note?: string | null; allowAnyEmail?: boolean; dryRun?: boolean }
): Promise<DraftResult[]> {
  const rate = Number.isFinite(opts.ratePct) ? Math.min(90, Math.max(1, Math.round((opts.ratePct as number) * 100) / 100)) : CREATOR_DEFAULT_RATE;
  const out: DraftResult[] = [];
  for (const e of entries) {
    const email = e.email.trim().toLowerCase();
    const name = e.name?.trim().slice(0, 120) || null;
    const channel = safeChannelUrl(e.channelUrl);
    const user = await db.user.findUnique({ where: { email }, select: { referralPartner: { select: { code: true } } } });
    if (user?.referralPartner) {
      out.push({ email, name, channel, status: "skipped", reason: `already a partner (${user.referralPartner.code})` });
      continue;
    }
    const existing = await db.partnerInvite.findFirst({
      where: { kind: "CREATOR", email, revokedAt: null },
      orderBy: { createdAt: "desc" },
    });
    if (existing) {
      out.push({ email, name, channel, status: "skipped", reason: `already invited (${creatorInviteState(existing)})` });
      continue;
    }
    if (opts.dryRun) {
      out.push({ email, name, channel, status: "would create" });
      continue;
    }
    await db.partnerInvite.create({
      data: {
        kind: "CREATOR",
        email,
        // A random hash nobody holds the preimage of: a draft can't be claimed.
        tokenHash: hashInviteToken(randomBytes(32).toString("base64url")),
        invitedById: opts.invitedById,
        expiresAt: new Date(), // real expiry is set when the invite is sent
        name,
        note: opts.note?.trim().slice(0, 500) || null,
        ratePct: rate,
        allowAnyEmail: !!opts.allowAnyEmail,
        channelUrl: channel,
        primaryGame: e.primaryGame?.trim().slice(0, 80) || null,
        country: e.country?.trim().slice(0, 80) || null,
        subscribers: e.subscribers?.trim().slice(0, 40) || null,
        lastSentAt: null,
        sendCount: 0,
      },
    });
    out.push({ email, name, channel, status: "created" });
  }
  return out;
}

// ---------- rendering + sending ----------

type RenderableInvite = { email: string; name: string | null; ratePct: number | null; allowAnyEmail: boolean };

/** The exact email a creator receives (the send path calls this too). */
export function renderCreatorInviteEmail(inv: RenderableInvite, claimUrl: string, expiresAt: Date): BuiltEmail {
  return emails.creatorPartnerInvite({
    name: inv.name,
    email: inv.email,
    ratePct: inv.ratePct ?? CREATOR_DEFAULT_RATE,
    claimUrl,
    expires: expiresAt.toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric", timeZone: "UTC" }),
    anyEmail: inv.allowAnyEmail,
  });
}

/** Preview: the same render with a token that matches no invite, and the expiry a send made now would get. */
export function renderCreatorInvitePreview(inv: RenderableInvite): BuiltEmail {
  return renderCreatorInviteEmail(inv, creatorClaimUrl(PREVIEW_TOKEN), new Date(Date.now() + CREATOR_INVITE_TTL_DAYS * 86_400_000));
}

/**
 * Send (or re-send) one creator invite: rotate the token (older links die),
 * set a fresh expiry, email it. Returns the new link ONCE (only its hash is
 * stored) so an admin can also deliver it by hand if mail isn't configured.
 */
export async function sendCreatorInvite(inviteId: string): Promise<{ ok: boolean; error?: string; email?: string; sent?: boolean; link?: string }> {
  const inv = await db.partnerInvite.findUnique({ where: { id: inviteId } });
  if (!inv || inv.kind !== "CREATOR") return { ok: false, error: "Invite not found." };
  if (inv.acceptedAt) return { ok: false, email: inv.email, error: "Already claimed." };
  if (inv.revokedAt) return { ok: false, email: inv.email, error: "Revoked — create a new invite instead." };

  const token = randomBytes(32).toString("base64url");
  const now = new Date();
  const updated = await db.partnerInvite.update({
    where: { id: inv.id },
    data: {
      tokenHash: hashInviteToken(token),
      expiresAt: new Date(now.getTime() + CREATOR_INVITE_TTL_DAYS * 86_400_000),
      lastSentAt: now,
      sendCount: { increment: 1 },
    },
  });
  const link = creatorClaimUrl(token);
  const tpl = renderCreatorInviteEmail(updated, link, updated.expiresAt);
  const { sendMail } = await import("./mailer");
  const sent = await sendMail({ to: updated.email, subject: tpl.subject, html: tpl.html, template: tpl.template });
  return { ok: true, email: updated.email, sent, link };
}

