// actions and the attachment routes — a "use server" file may only export async
// functions, so this constant lives here.

/** On-disk root for board attachments. Under /opt/nxeon so it can be read and
 *  acted on directly; gitignored (board-uploads/). */
export const BOARD_UPLOAD_DIR = process.env.NXEON_BOARD_UPLOAD_DIR ?? "/opt/nxeon/board-uploads";

// ---- Execution pipeline (shared client/server metadata) --------------------
