"use server";

// Creator Partner Program — CREATOR invites (2026-09-27).
//
// Extends the existing PartnerInvite mechanism (lib/actions-partner.ts —
// token → SHA-256 hash at rest, single use, expiry, revoke) with a second
// kind, "CREATOR": the admin creates DRAFT invites by email (optionally
// prefilled from the owner's creator CSV), previews the exact email, and sends
// explicitly. The creator claims it from their own signed-in account at
// /partner/claim?token=… and chooses their own sponsor code there
// (lib/partner-code.ts). The claim creates their ReferralPartner and seeds
// their Settings (name, invited email, channel link).
//
// Core logic (drafts, CSV matching, rendering, sending) lives in
// lib/partner-invite-core.ts so scripts/partner-invite-batch.ts shares it.
//
// Decisions (documented in docs/DOCUMENTATION.md, Creator Partner Program):
//  - NOTHING SENDS ON CREATE. Drafts go out only via adminSendCreatorInvites,
//    which the admin UI puts behind a confirm listing count + recipients.
//  - EMAIL MATCH: the claiming account's email must equal the invited email,
//    unless the admin ticked "allow a different email" on the invite.
//  - CODES are case-insensitive, stored UPPERCASE, 3–8 letters/digits, and
//    must not collide (case-insensitively) with another partner code, a coupon
//    code, or any customer's peer-referral code (register() resolves a `ref`
//    against partner codes FIRST, so a collision would hijack that customer's
//    referral link).
//  - Each send ROTATES the token (old link dies) and resets the expiry.

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { headers } from "next/headers";
import { promises as fs } from "node:fs";
import { db } from "./db";
import { requireArea } from "./rbac";
import { requireUser, assertNotImpersonating } from "./auth";
import { checkRateLimit, clientIp } from "./rate-limit";
import { checkSponsorCodeFormat } from "./partner-code";
import {
  CREATOR_DEFAULT_RATE,
  createCreatorDrafts,
  findMasterCreatorCsv,
  hashInviteToken,
  matchCreators,
  normalizeEmails,
  parseCreatorCsv,
  safeChannelUrl,
  sendCreatorInvite,
  type DraftResult,
} from "./partner-invite-core";

const MAX_BATCH = 50;
const MAX_CSV_BYTES = 2 * 1024 * 1024;

// ---------- Admin: create drafts ----------

export type CreateDraftsState = { error?: string; results?: DraftResult[]; unmatched?: string[]; source?: string };

export async function adminCreateCreatorDrafts(_prev: CreateDraftsState, fd: FormData): Promise<CreateDraftsState> {
  const admin = await requireArea("billing");

  const { emails, invalid } = normalizeEmails(String(fd.get("emails") ?? ""));
  if (invalid.length) return { error: `Not a valid email: ${invalid.slice(0, 3).join(", ")}` };
  if (emails.length === 0) return { error: "Enter at least one email address." };
  if (emails.length > MAX_BATCH) return { error: `At most ${MAX_BATCH} emails at a time (or use scripts/partner-invite-batch.ts).` };

  const note = String(fd.get("note") ?? "").trim().slice(0, 500) || null;
  const rateRaw = Number(fd.get("ratePct") ?? CREATOR_DEFAULT_RATE);
  const ratePct = Number.isFinite(rateRaw) ? rateRaw : CREATOR_DEFAULT_RATE;
  const allowAnyEmail = fd.get("allowAnyEmail") === "on";
  const source = String(fd.get("source") ?? "master");

  let entries: { email: string; name?: string | null; channelUrl?: string | null; primaryGame?: string | null; country?: string | null; subscribers?: string | null }[];
  let unmatched: string[] = [];
  let sourceLabel = "";

  if (source === "manual") {
    if (emails.length > 1) return { error: "Manual name/channel applies to one email — use a CSV to prefill several." };
    const channel = String(fd.get("channelUrl") ?? "").trim();
    if (channel && !safeChannelUrl(channel)) return { error: "Channel link must be an http(s) URL." };
    entries = [{ email: emails[0], name: String(fd.get("name") ?? "").trim() || null, channelUrl: channel || null }];
    sourceLabel = "entered by hand";
  } else {
    let text: string;
    if (source === "upload") {
      const file = fd.get("csv");
      if (!(file instanceof File) || file.size === 0) return { error: "Choose a CSV file to match against." };
      if (file.size > MAX_CSV_BYTES) return { error: "That CSV is over 2 MB." };
      text = await file.text();
      sourceLabel = `uploaded ${file.name}`;
    } else {
      const master = await findMasterCreatorCsv();
      if (!master) return { error: "No master creator list found on the board — upload the CSV instead." };
      try {
        text = await fs.readFile(master.path, "utf8");
      } catch {
        return { error: "The master creator list couldn't be read from disk." };
      }
      sourceLabel = master.filename;
    }
    const parsed = parseCreatorCsv(text);
    if (parsed.error) return { error: parsed.error };
    const m = matchCreators(emails, parsed.rows);
    unmatched = m.unmatched;
    entries = m.matched.map(({ email, row }) => ({
      email,
      name: row.name,
      channelUrl: row.channel,
      primaryGame: row.game,
      country: row.country,
      subscribers: row.subscribers,
    }));
  }

  const results = entries.length
    ? await createCreatorDrafts(entries, { invitedById: admin.id, ratePct, note, allowAnyEmail })
    : [];
  const created = results.filter((r) => r.status === "created").length;
  await db.auditLog.create({
