export function SendAllDraftsButton({ drafts }: { drafts: { email: string; name: string | null }[] }) {
  const [pending, start] = useTransition();
  const [res, setRes] = useState<{ error?: string; results?: SendResult[] } | null>(null);
  if (drafts.length === 0 && !res) return null;
  return (
    <div className="space-y-2">
      {drafts.length > 0 && (
        <button
          type="button"
          className="btn-primary"
          disabled={pending}
          onClick={() => {
            const list = drafts.map((d) => `  • ${d.email}${d.name ? ` (${d.name})` : ""}`).join("\n");
