export function SendCreatorInviteButton({ inviteId, email, name, resend }: { inviteId: string; email: string; name: string | null; resend: boolean }) {
  const [pending, start] = useTransition();
  const [res, setRes] = useState<{ error?: string; results?: SendResult[] } | null>(null);
  return (
    <span className="inline-flex flex-col items-end gap-1">
      <button
        type="button"
        className="text-xs font-semibold text-brand-300 hover:underline disabled:opacity-50"
        disabled={pending}
        onClick={() => {
          const who = `${email}${name ? ` (${name})` : ""}`;
          const msg = resend
            ? `Resend the invite to 1 creator?\n\n  • ${who}\n\nA new link is issued and the previous one stops working.`
            : `Email this creator invite now?\n\n  • ${who}\n\nThis sends a real email.`;
