          start(async () => setRes(await adminSendCreatorInvites([inviteId])));
        }}
      >
        {pending ? "Sending…" : resend ? "Resend" : "Send"}
      </button>
      {res?.error && <span className="text-xs text-red-400">{res.error}</span>}
      {res?.results && <span className="w-[340px] max-w-[70vw]"><SendResults results={res.results} /></span>}
    </span>
  );
}

export function PreviewCreatorInviteButton({ inviteId }: { inviteId: string }) {
  const [pending, start] = useTransition();
  const [p, setP] = useState<{ error?: string; to?: string; subject?: string; html?: string } | null>(null);
  return (
    <>
      <button
        type="button"
        className="text-xs font-semibold text-slate-300 hover:underline disabled:opacity-50"
        disabled={pending}
        onClick={() => (p ? setP(null) : start(async () => setP(await adminPreviewCreatorInvite(inviteId))))}
