        <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-black/70 p-4" onClick={() => setP(null)}>
          <div className="mt-6 w-full max-w-[720px] overflow-hidden rounded-2xl border border-white/10 bg-navy-900 text-left" onClick={(e) => e.stopPropagation()}>
            <div className="space-y-1 border-b border-white/[0.06] px-4 py-3 text-sm">
              <p><span className="text-slate-500">To:</span> <span className="font-mono text-slate-200">{p.to}</span></p>
              <p><span className="text-slate-500">Subject:</span> <span className="text-slate-100">{p.subject}</span></p>
              <p className="text-[11px] text-slate-500">
                Exactly what the send path renders, with a placeholder link that matches no invite. Delivery adds only an
                invisible open-tracking pixel.
              </p>
            </div>
            <iframe title="Creator invite email preview" srcDoc={p.html} sandbox="" className="h-[720px] w-full border-0 bg-white" />
