/**
 * Create a batch of Creator Partner DRAFT invites from a list of emails,
 * prefilled from the owner's creator CSV. NEVER sends anything — drafts go out
 * only when an admin presses Send / "Send all drafts" on /admin/partners.
 * See docs/DOCUMENTATION.md, "Inviting a batch of creators — the runbook".
 *
 *   # what would happen (reads the DB, writes nothing)
 *   NXEON_DB_TARGET=nxeon npx tsx scripts/partner-invite-batch.ts --emails batch.txt --csv creators.csv --dry-run
 *   # create the drafts
 *   NXEON_DB_TARGET=nxeon npx tsx scripts/partner-invite-batch.ts --emails batch.txt --csv creators.csv
 *   # render one creator's email to a file for review (writes nothing to the DB)
 *   npx tsx scripts/partner-invite-batch.ts --csv creators.csv --preview someone@example.com [--out preview.html]
 *
 * Options:
 *   --emails <file>   emails, one per line (commas/spaces also fine). A .json file
 *                     that is an array of {email} objects (or strings) works too.
 *   --csv <file>      the creator list: Name, Youtube Channel, Primary game, Email,
 *                     Current Hosting Sponsor (If Applicable), Country, Subscriber count, Emailed
 *   --dry-run         print the table, write nothing
 *   --rate <pct>      lifetime commission for these invites (default 40)
 *   --note <text>     internal note stored on each invite
 *   --any-email       let the creator claim from an account with a different email
 *   --preview <email> render that creator's invite email (from their existing invite,
 *                     else from the CSV row) with a placeholder link; no DB writes
 *   --out <file>      where --preview writes (default ./creator-invite-preview.html)
 *
 * Idempotent: an email that already has a (non-revoked) creator invite — draft,
 * sent, accepted or expired — or whose account is already a partner is skipped.
 * Emails not found in the CSV are listed as "unmatched" and get no draft.
 * DATABASE_URL comes from the environment like every other script here; writes
 * additionally require NXEON_DB_TARGET to name that database (scripts/db-target-guard.ts).
 */

import { readFileSync, writeFileSync } from "node:fs";
import { assertDbTarget } from "./db-target-guard";
import { db } from "../lib/db";
import {
  createCreatorDrafts,
  matchCreators,
  normalizeEmails,
  parseCreatorCsv,
  renderCreatorInvitePreview,
  CREATOR_DEFAULT_RATE,
} from "../lib/partner-invite-core";

function arg(name: string): string | undefined {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 ? process.argv[i + 1] : undefined;
}
const flag = (name: string) => process.argv.includes(`--${name}`);

function readEmails(path: string): string[] {
  const raw = readFileSync(path, "utf8");
  if (path.endsWith(".json")) {
    const j = JSON.parse(raw) as unknown;
    if (!Array.isArray(j)) throw new Error(`${path}: expected a JSON array`);
    return j.map((x) => (typeof x === "string" ? x : String((x as { email?: string }).email ?? ""))).filter(Boolean).map((e) => e.trim().toLowerCase());
  }
  const { emails, invalid } = normalizeEmails(raw);
  if (invalid.length) throw new Error(`Not valid email addresses: ${invalid.join(", ")}`);
  return emails;
}

function table(rows: string[][]) {
  const w = rows[0].map((_, c) => Math.min(48, Math.max(...rows.map((r) => (r[c] ?? "").length))));
  for (const r of rows) console.log(r.map((v, c) => (v ?? "").slice(0, 48).padEnd(w[c])).join("  "));
}

async function main() {
  const csvPath = arg("csv");
  const preview = arg("preview");

  if (preview) {
    const email = preview.trim().toLowerCase();
    const inv = await db.partnerInvite.findFirst({ where: { kind: "CREATOR", email, revokedAt: null }, orderBy: { createdAt: "desc" } }).catch(() => null);
    let source: { email: string; name: string | null; ratePct: number | null; allowAnyEmail: boolean };
    if (inv) {
      source = inv;
      console.log(`Rendering from the existing invite for ${email}.`);
    } else {
      if (!csvPath) throw new Error(`No invite exists for ${email}; pass --csv to render from the creator list.`);
      const { rows, error } = parseCreatorCsv(readFileSync(csvPath, "utf8"));
      if (error) throw new Error(error);
      const row = rows.find((r) => r.email === email);
      if (!row) throw new Error(`${email} is not in ${csvPath}.`);
      source = { email, name: row.name || null, ratePct: Number(arg("rate") ?? CREATOR_DEFAULT_RATE), allowAnyEmail: flag("any-email") };
      console.log(`Rendering from the CSV row for ${email} (no invite in the database yet).`);
    }
    const tpl = renderCreatorInvitePreview(source);
    const out = arg("out") ?? "creator-invite-preview.html";
    writeFileSync(out, tpl.html, "utf8");
    console.log(`To:      ${source.email}\nSubject: ${tpl.subject}\nWritten: ${out}\n(The link in it is a placeholder that matches no invite.)`);
    return;
  }

  const emailsPath = arg("emails");
  if (!emailsPath || !csvPath) throw new Error("Usage: --emails <file> --csv <creators.csv> [--dry-run] (see the header of this file)");
  const dryRun = flag("dry-run");
  if (!dryRun) assertDbTarget("partner-invite-batch.ts");

  const emails = [...new Set(readEmails(emailsPath))];
  const { rows, error } = parseCreatorCsv(readFileSync(csvPath, "utf8"));
  if (error) throw new Error(error);
  const { matched, unmatched } = matchCreators(emails, rows);

  const results = await createCreatorDrafts(
    matched.map(({ email, row }) => ({ email, name: row.name, channelUrl: row.channel, primaryGame: row.game, country: row.country, subscribers: row.subscribers })),
    {
      invitedById: null,
      ratePct: Number(arg("rate") ?? CREATOR_DEFAULT_RATE),
      note: arg("note") ?? null,
      allowAnyEmail: flag("any-email"),
      dryRun,
    }
  );

  const out: string[][] = [["EMAIL", "NAME", "CHANNEL", "RESULT"]];
  for (const r of results) out.push([r.email, r.name ?? "", r.channel ?? "", r.status === "skipped" ? `skipped: ${r.reason}` : r.status]);
  for (const e of unmatched) out.push([e, "", "", "unmatched: not in the CSV — no draft"]);
  table(out);
  const created = results.filter((r) => r.status === "created" || r.status === "would create").length;
  console.log(
    `\n${dryRun ? "[dry run] would create" : "created"} ${created} draft(s); skipped ${results.length - created}; unmatched ${unmatched.length}. ` +
      `Nothing was emailed — preview and send from /admin/partners.`
  );
}

main()
  .then(() => db.$disconnect())
  .then(() => process.exit(0))
  .catch(async (e) => {
    console.error(e instanceof Error ? e.message : e);
    await db.$disconnect().catch(() => {});
    process.exit(1);
  });

